import React, { useState, useMemo } from 'react';
import { useApp } from '../context/AppContext';
import { Calculator, AlertTriangle, HelpCircle, X } from 'lucide-react';
import { Product } from '../types';

const Pricing: React.FC = () => {
  const { 
    cfi, 
    platformConfig, 
    calculateFixedCostPercent,
    updateProduct,
    getSortedProducts,
    getProductCMV
  } = useApp();
  const [showHelp, setShowHelp] = useState(false);

  const fixedCostPct = calculateFixedCostPercent();
  const avgCardRate = (cfi.debitTax + cfi.creditTax) / 2;
  const variableCostsPct = avgCardRate + cfi.tax + cfi.royalties + cfi.marketing + cfi.voucherTax;
  const totalCfiCost = fixedCostPct + variableCostsPct;

  const sortedProducts = useMemo(() => getSortedProducts(), [getSortedProducts]);

  const calculateStorePrice = (cmv: number, profitMargin: number) => {
    const totalDeductions = (totalCfiCost + profitMargin) / 100;
    if (totalDeductions >= 1) return 0; 
    return cmv / (1 - totalDeductions);
  };

  const calculateMarketplacePrice = (pvLoja: number, feesPct: number, delivery: number, ci: number, coupon: number) => {
      const denominator = 1 - (feesPct / 100);
      if (denominator <= 0) return 0;
      return (pvLoja + delivery + ci + coupon) / denominator;
  };

  const handleUpdate = (productId: string, key: string, value: number) => {
      const product = sortedProducts.find(p => p.id === productId);
      if (!product) return;
      const newPricing = { ...product.pricing };
      if (key.includes('.')) {
          const [parent, child] = key.split('.');
          // @ts-ignore
          newPricing[parent] = { ...newPricing[parent], [child]: value };
      } else {
          // @ts-ignore
          newPricing[key] = value;
      }
      updateProduct(productId, { pricing: newPricing });
  };

  return (
    <div className="space-y-6 pb-20 animate-fade-in">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
          <h2 className="text-3xl font-bold text-gray-900 dark:text-white uppercase">Preço de Venda</h2>
          <p className="text-gray-500 dark:text-gray-400">Sugestão de preços baseada na ordem definida na Ficha Técnica.</p>
        </div>
        <div className="bg-white dark:bg-gray-900 p-4 rounded-xl border border-gray-200 dark:border-gray-800 shadow-lg flex gap-4 items-center">
            <span className="text-[10px] text-gray-500 uppercase font-bold">CFI Operacional</span>
            <span className="text-xl font-bold text-brand-red">{totalCfiCost.toFixed(2)}%</span>
        </div>
      </div>

      <div className="bg-white dark:bg-gray-900 border border-gray-200 dark:border-gray-800 rounded-xl overflow-hidden shadow-xl">
        <div className="overflow-x-auto pb-2">
            <table className="w-full text-left border-collapse min-w-[2000px]">
            <thead>
                <tr className="bg-gray-50 dark:bg-[#0f111a] text-gray-500 dark:text-gray-400 text-[10px] uppercase font-bold tracking-wider">
                    <th className="p-3 sticky left-0 z-30 bg-gray-50 dark:bg-[#0f111a] w-56 shadow-md">Produto</th>
                    <th className="p-3 text-center w-24">CMV</th>
                    <th className="p-3 text-center w-20">CFI %</th>
                    <th className="p-3 text-center w-24">Lucro %</th>
                    <th className="p-3 text-center w-32 bg-gray-100 dark:bg-gray-800 text-gray-900 dark:text-white border-x">PV Loja</th>
                    <th className="p-3 text-center w-32 bg-brand-red text-white">PV Ifood</th>
                    <th className="p-3 text-center w-32 bg-purple-600 text-white">PV Ifood CI</th>
                    <th className="p-3 text-center w-32 bg-yellow-600 text-white">PV 99Food</th>
                    <th className="p-3 text-center w-32 bg-orange-600 text-white">PV Keeta</th>
                </tr>
            </thead>
            <tbody className="divide-y divide-gray-100 dark:divide-gray-800 text-xs">
                {sortedProducts.map(product => {
                    const cmv = getProductCMV(product);
                    const pricing = product.pricing || {};
                    const profitMargin = pricing.profitMargin !== undefined ? pricing.profitMargin : 20; 
                    const storePrice = calculateStorePrice(cmv, profitMargin);

                    // Ifood
                    const ifoodFee = pricing.ifood?.fee ?? platformConfig.ifood.fee;
                    const ifoodOnline = pricing.ifood?.onlinePayment ?? platformConfig.ifood.onlinePayment;
                    const ifoodAntic = pricing.ifood?.anticipation ?? platformConfig.ifood.anticipation;
                    const ifoodDel = pricing.ifood?.delivery ?? platformConfig.ifood.delivery;
                    const ifoodCoupon = pricing.ifood?.coupon ?? 0;
                    const ifoodPrice = calculateMarketplacePrice(storePrice, ifoodFee + ifoodOnline + ifoodAntic, ifoodDel, 0, ifoodCoupon);

                    // Ifood CI
                    const ciVal = pricing.ifood?.ciValue ?? platformConfig.ifood.ciValue;
                    const ifoodCIPrice = calculateMarketplacePrice(storePrice, ifoodFee + ifoodOnline + ifoodAntic, ifoodDel, ciVal, ifoodCoupon);

                    // 99Food
                    const f99Total = platformConfig.food99.fee + platformConfig.food99.onlinePayment;
                    const food99Price = calculateMarketplacePrice(storePrice, f99Total, platformConfig.food99.delivery, 0, 0);

                    // Keeta
                    const keetaTotal = platformConfig.keeta.fee + platformConfig.keeta.onlinePayment;
                    const keetaPrice = calculateMarketplacePrice(storePrice, keetaTotal, platformConfig.keeta.delivery, 0, 0);

                    return (
                        <tr key={product.id} className="hover:bg-gray-50 dark:hover:bg-gray-800/30 transition group">
                            <td className="p-3 font-bold text-gray-900 dark:text-white sticky left-0 z-20 bg-white dark:bg-gray-900 border-r shadow-sm">
                                {product.name}
                                <span className="block text-[8px] text-gray-400 uppercase font-normal">{product.category}</span>
                            </td>
                            <td className="p-3 text-center font-mono">R$ {cmv.toFixed(2)}</td>
                            <td className="p-3 text-center">{totalCfiCost.toFixed(2)}%</td>
                            <td className="p-3 text-center">
                                <input type="number" className="w-12 text-center bg-gray-50 dark:bg-gray-800 rounded p-1" value={profitMargin} onChange={e => handleUpdate(product.id, 'profitMargin', parseFloat(e.target.value))} />
                            </td>
                            <td className="p-3 text-center font-bold text-base bg-gray-100 dark:bg-gray-800">R$ {storePrice.toFixed(2)}</td>
                            <td className="p-3 text-center font-bold text-base bg-red-50 dark:bg-red-950/20 text-brand-red">R$ {ifoodPrice.toFixed(2)}</td>
                            <td className="p-3 text-center font-bold text-base bg-purple-50 dark:bg-purple-950/20 text-purple-600">R$ {ifoodCIPrice.toFixed(2)}</td>
                            <td className="p-3 text-center font-bold text-base bg-yellow-50 dark:bg-yellow-950/20 text-yellow-600">R$ {food99Price.toFixed(2)}</td>
                            <td className="p-3 text-center font-bold text-base bg-orange-50 dark:bg-orange-950/20 text-orange-600">R$ {keetaPrice.toFixed(2)}</td>
                        </tr>
                    );
                })}
            </tbody>
            </table>
        </div>
      </div>
    </div>
  );
};

export default Pricing;

