                        >
                            {sortedCategories.map(cat => <option key={cat.id} value={cat.name}>{cat.name}</option>)}
                            <option value="Geral">Geral</option>
                        </select>
                     </div>
                  </div>

                  {editingProduct && (
                     <>
                        <div className="flex items-center justify-between">
                           <h4 className="text-gray-900 dark:text-white font-bold uppercase text-sm">Composição</h4>
                           <select className="bg-white dark:bg-gray-800 text-xs p-2 rounded border border-gray-300 dark:text-white" onChange={(e) => { 
                               if(!e.target.value) return;
                               const newIngs = [...editingProduct.ingredients, { ingredientId: e.target.value, quantity: 1 }];
                               updateProduct(editingProduct.id, { ingredients: newIngs });
                               setEditingProduct({ ...editingProduct, ingredients: newIngs });
                               e.target.value = "";
                           }}>
                              <option value="">+ Adicionar Insumo</option>
                              {ingredients.map(i => <option key={i.id} value={i.id}>{i.name}</option>)}
                           </select>
                        </div>
                        <div className="bg-white dark:bg-gray-950 border border-gray-200 dark:border-gray-800 rounded-xl overflow-hidden">
                           <table className="w-full text-left">
                              <thead className="bg-gray-50 dark:bg-gray-900 text-gray-500 text-[10px] uppercase font-bold">
                                 <tr>
                                    <th className="px-4 py-2">Insumo</th>
                                    <th className="px-4 py-2 text-center">Unidade</th>
                                    <th className="px-4 py-2 text-center">Qtd. Receita</th>
                                    <th className="px-4 py-2 text-right">Subtotal</th>
                                    <th className="px-4 py-2 w-10"></th>
                                 </tr>
                              </thead>
                              <tbody className="divide-y divide-gray-100 dark:divide-gray-800 text-sm">
                                 {editingProduct.ingredients.map((item, idx) => {
                                    const ing = ingredients.find(i => i.id === item.ingredientId);
                                    if(!ing) return null;
                                    return (
                                       <tr key={idx}>
                                          <td className="px-4 py-2 font-medium dark:text-white">{ing.name}</td>
                                          <td className="px-4 py-2 text-center text-xs text-gray-500">{ing.unit}</td>
                                          <td className="px-4 py-2 text-center">
                                             <input type="number" step="0.001" value={item.quantity} onChange={(e) => {
                                                 const val = parseFloat(e.target.value);
                                                 const newIngs = [...editingProduct.ingredients];
                                                 newIngs[idx].quantity = val;
                                                 updateProduct(editingProduct.id, { ingredients: newIngs });
                                                 setEditingProduct({ ...editingProduct, ingredients: newIngs });
                                             }} className="bg-gray-50 dark:bg-gray-800 text-gray-900 dark:text-white w-20 text-center rounded p-1" />
                                          </td>
                                          <td className="px-4 py-2 text-right font-bold dark:text-white">R$ {(getIngredientRealCost(ing) * item.quantity).toFixed(2)}</td>
                                          <td className="px-4 py-2 text-right">
                                             <button onClick={() => {
                                                 const newIngs = editingProduct.ingredients.filter((_, i) => i !== idx);
                                                 updateProduct(editingProduct.id, { ingredients: newIngs });
                                                 setEditingProduct({ ...editingProduct, ingredients: newIngs });
                                             }} className="text-red-400 hover:text-red-600"><Trash size={14} /></button>
                                          </td>
                                       </tr>
                                    );
                                 })}
                              </tbody>
                           </table>
                        </div>
                     </>
                  )}
               </div>

               <div className="p-6 border-t border-gray-200 dark:border-gray-800 bg-gray-50 dark:bg-gray-900 flex justify-between items-center">
                  {editingProduct && (
                     <div>
                        <span className="text-xs text-gray-500 uppercase font-bold">Custo Total (CMV)</span>
                        <span className="text-2xl font-bold text-brand-red block">R$ {getProductCMV(editingProduct).toFixed(2)}</span>
                     </div>
                  )}
                  <div className="flex gap-3">
                     <button onClick={() => setIsModalOpen(false)} className="px-6 py-2 rounded-lg bg-white dark:bg-gray-800 text-gray-700 dark:text-white font-bold border">Fechar</button>
                     <button onClick={handleSaveProduct} className="px-6 py-2 rounded-lg bg-brand-red hover:bg-red-700 text-white font-bold shadow-lg">Salvar Produto</button>
                  </div>
               </div>
            </div>
         </div>
       )}
    </div>
  );
};

