import React, { useState, useEffect, useLayoutEffect } from 'react';
import { AppProvider } from './context/AppContext';
import Sidebar from './components/Sidebar';
import Dashboard from './pages/Dashboard';
import Ingredients from './pages/Ingredients';
import Products from './pages/Products';
import Pricing from './pages/Pricing';
import Expenses from './pages/Expenses';
import Dna from './pages/Dna';
import FinancialCategories from './pages/FinancialCategories';
import Billing from './pages/Billing';
import Profit from './pages/Profit';
import Combos from './pages/Combos';
import StoreList from './pages/StoreList';
import Help from './pages/Help';
import { StoreInfo, GlobalState } from './types';
import { INITIAL_STATE, EMPTY_STATE, BACKGROUND_PALETTE } from './constants';

// Chaves originais para garantir que os dados antigos voltem
const STORAGE_KEY_DATA = 'lucro_facil_pro_data';
const STORAGE_KEY_STORES = 'lucro_facil_pro_stores';
const STORAGE_KEY_LAST_BACKUP = 'lucro_facil_last_backup_date';

// Chaves da V3 (para caso o usuário já tenha começado a cadastrar algo na nova)
const STORAGE_KEY_DATA_V3 = 'lucro_facil_pro_data_v3';
const STORAGE_KEY_STORES_V3 = 'lucro_facil_pro_stores_v3';

interface AppContentProps {
  onLogout: () => void;
  bgColor: string;
  onBgColorChange: (color: string) => void;
  onBackup: () => void;
  onRestore: (file: File) => void;
  lastBackupDate: string | null;
}

const AppContent: React.FC<AppContentProps> = ({ onLogout, bgColor, onBgColorChange, onBackup, onRestore, lastBackupDate }) => {
  const [activeTab, setActiveTab] = useState('dashboard');

  const renderContent = () => {
    switch (activeTab) {
      case 'dashboard': return <Dashboard />;
      case 'expenses': return <Expenses />;
      case 'categories': return <FinancialCategories />;
      case 'billing': return <Billing />;
      case 'dna': return <Dna />;
      case 'ingredients': return <Ingredients />;
      case 'products': return <Products />;
      case 'pricing': return <Pricing />;
      case 'profit': return <Profit />;
      case 'combos': return <Combos />;
      case 'help': return <Help />;
      default: return <Dashboard />;
    }
  };

  return (
    <div className="flex min-h-screen transition-colors duration-500">
      <Sidebar 
        activeTab={activeTab} 
        setActiveTab={setActiveTab} 
        onLogout={onLogout} 
        bgColor={bgColor}
        onBgColorChange={onBgColorChange}
        onBackup={onBackup}
        onRestore={onRestore}
        lastBackupDate={lastBackupDate}
      />
      <main className="flex-1 ml-64 p-8">
        {renderContent()}
      </main>
    </div>
  );
};

const App: React.FC = () => {
  const [selectedStoreId, setSelectedStoreId] = useState<string | null>(null);

  const [bgColor, setBgColor] = useState(() => {
    if (typeof window !== 'undefined') {
      return localStorage.getItem('app_bg_color') || BACKGROUND_PALETTE[0].color;
    }
    return BACKGROUND_PALETTE[0].color;
  });

  const [lastBackupDate, setLastBackupDate] = useState<string | null>(() => {
    if (typeof window !== 'undefined') {
      return localStorage.getItem(STORAGE_KEY_LAST_BACKUP);
    }
    return null;
  });

  useLayoutEffect(() => {
    const root = window.document.documentElement;
    const selectedPalette = BACKGROUND_PALETTE.find(p => p.color === bgColor) || BACKGROUND_PALETTE[0];

    if (selectedPalette.mode === 'dark') {
      root.classList.add('dark');
    } else {
      root.classList.remove('dark');
    }

    root.style.setProperty('--app-bg', bgColor);
    localStorage.setItem('app_bg_color', bgColor);
  }, [bgColor]);

  const handleBgColorChange = (color: string) => {
    setBgColor(color);
  };

  // -- LOGICA DE RECUPERAÇÃO DE DADOS --

  const [stores, setStores] = useState<StoreInfo[]>(() => {
    try {
      // Tenta a v3 primeiro, se não tiver nada, tenta a original
      const savedV3 = localStorage.getItem(STORAGE_KEY_STORES_V3);
      if (savedV3 && JSON.parse(savedV3).length > 0) return JSON.parse(savedV3);

      const savedOriginal = localStorage.getItem(STORAGE_KEY_STORES);
      if (savedOriginal) return JSON.parse(savedOriginal);
    } catch (e) {
      console.error('Falha ao carregar lojas');
    }
    return [{ id: '1', name: 'Minha Hamburgueria', address: '' }];
  });

  const [storesData, setStoresData] = useState<Record<string, GlobalState>>(() => {
    try {
      const savedV3 = localStorage.getItem(STORAGE_KEY_DATA_V3);
      const savedOriginal = localStorage.getItem(STORAGE_KEY_DATA);

      // Se tiver v3, prioriza ela, senão pega a original
      const data = savedV3 ? JSON.parse(savedV3) : (savedOriginal ? JSON.parse(savedOriginal) : {});

      if (Object.keys(data).length > 0) return data;
    } catch (e) {
      console.error('Falha ao carregar dados das lojas');
    }
    return { '1': INITIAL_STATE };
  });

  // -- AUTO SAVE (Salva em ambas as chaves para segurança agora) --
  useEffect(() => {
    try {
      const storesJson = JSON.stringify(stores);
      const dataJson = JSON.stringify(storesData);

      localStorage.setItem(STORAGE_KEY_STORES, storesJson);
      localStorage.setItem(STORAGE_KEY_DATA, dataJson);

      // Mantém v3 atualizada também
      localStorage.setItem(STORAGE_KEY_STORES_V3, storesJson);
      localStorage.setItem(STORAGE_KEY_DATA_V3, dataJson);
    } catch (e) {
      console.error('Erro no auto-save', e);
    }
  }, [stores, storesData]);

  const handleBackup = () => {
    const backupData = {
      version: '3.0',
      date: new Date().toISOString(),
      stores,
      storesData
    };
    const blob = new Blob([JSON.stringify(backupData, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `Backup_LucroFacil_${new Date().toISOString().split('T')[0]}.json`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
    const nowISO = new Date().toISOString();
    setLastBackupDate(nowISO);
    localStorage.setItem(STORAGE_KEY_LAST_BACKUP, nowISO);
  };

  const handleRestore = (file: File) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const content = e.target?.result as string;
        const parsed = JSON.parse(content);
        if (parsed.stores && parsed.storesData) {
          if (window.confirm('Restaurar backup? Isso substituirá tudo.')) {
            setStores(parsed.stores);
            setStoresData(parsed.storesData);
            alert('Dados restaurados!');
            window.location.reload();
          }
        }
      } catch (err) {
        alert('Erro no arquivo.');
      }
    };
    reader.readAsText(file);
  };

  const handleAddStore = (store: StoreInfo) => {
    const newId = Date.now().toString();
    const newStore = { ...store, id: newId };
    setStores([...stores, newStore]);
    setStoresData(prev => ({ ...prev, [newId]: { ...EMPTY_STATE, storeInfo: newStore } }));
  };

  const handleUpdateStore = (store: StoreInfo) => {
    setStores(stores.map(s => s.id === store.id ? store : s));
    if (store.id && storesData[store.id]) {
      setStoresData(prev => ({ ...prev, [store.id!]: { ...prev[store.id!], storeInfo: store } }));
    }
  };

  const handleDeleteStore = (id: string) => {
    if (!window.confirm('Excluir esta loja?')) return;
    setStores(prev => prev.filter(s => s.id !== id));
    setStoresData(prev => {
      const newData = { ...prev };
      delete newData[id];
      return newData;
    });
  };

  const handleStateChange = (newState: GlobalState) => {
    if (selectedStoreId) {
      setStoresData(prev => ({ ...prev, [selectedStoreId]: newState }));
    }
  };

  const handleReplicate = (sourceId: string, targetId: string, type: string) => {
    const source = storesData[sourceId];
    const target = storesData[targetId];
    if (!source || !target) return;
    let newData = { ...target };
    if (type === 'all') newData = { ...source, storeInfo: target.storeInfo };
    else {
        switch (type) {
            case 'ingredients': newData.ingredients = [...source.ingredients]; break;
            case 'products': newData.products = [...source.products]; break;
            case 'combos': newData.combos = [...source.combos]; break;
            case 'expenses': newData.expenses = [...source.expenses]; break;
            case 'cfi': newData.cfi = { ...source.cfi }; break;
        }
    }
    setStoresData(prev => ({ ...prev, [targetId]: newData }));
  };

  const selectedStoreInfo = stores.find(s => s.id === selectedStoreId);
  const currentStoreData = selectedStoreId ? storesData[selectedStoreId] : undefined;

  if (!selectedStoreId) {
    return (
      <StoreList 
        stores={stores}
        onSelectStore={(id) => setSelectedStoreId(id)} 
        onAddStore={handleAddStore}
        onUpdateStore={handleUpdateStore}
        onDeleteStore={handleDeleteStore}
        onReplicate={handleReplicate}
      />
    );
  }

  return (
    <AppProvider 
      storeId={selectedStoreId} 
      initialData={currentStoreData}
      onStateChange={handleStateChange}
    >
      <AppContent 
        onLogout={() => setSelectedStoreId(null)} 
        bgColor={bgColor}
        onBgColorChange={handleBgColorChange}
        onBackup={handleBackup}
        onRestore={handleRestore}
        lastBackupDate={lastBackupDate}
      />
    </AppProvider>
  );
};

export default App;

import React, { createContext, useContext, useState, ReactNode, useEffect, useRef } from 'react';
import { GlobalState, Ingredient, Product, Expense, MonthlyData, CfiConfig, PlatformConfig, Category, Supplier, FixedCostMode, Combo, StoreInfo, MenuCategory } from '../types';
import { INITIAL_STATE, EMPTY_STATE, INITIAL_MENU_CATEGORIES } from '../constants';

interface AppContextType extends GlobalState {
  addIngredient: (ing: Ingredient) => void;
  updateIngredient: (id: string, ing: Partial<Ingredient>) => void;
  deleteIngredient: (id: string) => void;

  addProduct: (prod: Product) => void;
  updateProduct: (id: string, prod: Partial<Product>) => void;
  deleteProduct: (id: string) => void;
  reorderProduct: (id: string, direction: 'up' | 'down') => void;

  addMenuCategory: (name: string) => void;
  deleteMenuCategory: (id: string) => void;
  reorderMenuCategory: (id: string, direction: 'up' | 'down') => void;

  addCombo: (combo: Combo) => void;
  updateCombo: (id: string, combo: Partial<Combo>) => void;
  deleteCombo: (id: string) => void;

  addExpense: (exp: Expense) => void;
  updateExpense: (id: string, exp: Partial<Expense>) => void;
  addExpenseWithInstallments: (baseExp: Omit<Expense, 'id' | 'installment'>, installments: number) => void;

  addCategory: (cat: Category) => void;
  deleteCategory: (id: string) => void;

  addSupplier: (sup: Supplier) => void;
  deleteSupplier: (id: string) => void;

  updateCfi: (cfi: Partial<CfiConfig>) => void;
  updatePlatformConfig: (cfg: Partial<PlatformConfig>) => void;
  updateMonthlyRevenue: (data: MonthlyData[]) => void;
  updateStoreInfo: (info: Partial<StoreInfo>) => void;

  setFixedCostMode: (mode: FixedCostMode) => void;

  getIngredientRealCost: (ing: Ingredient) => number;
  getProductCMV: (prod: Product) => number;
  calculateFixedCostPercent: (currentMonth?: string) => number;
  calculateTotalCfiPercent: () => number;
  getSortedProducts: () => Product[];
}

const AppContext = createContext<AppContextType | undefined>(undefined);

export const AppProvider: React.FC<{ 
  children: ReactNode; 
  storeId: string;
  initialData?: GlobalState;
  onStateChange?: (newState: GlobalState) => void;
}> = ({ children, storeId, initialData, onStateChange }) => {

  const [state, setState] = useState<GlobalState>(() => {
    // 1. Carrega os dados (seja inicialData do App.tsx ou defaults)
    const data = initialData || (storeId === '1' ? INITIAL_STATE : EMPTY_STATE);

    // 2. MIGRAÇÃO DE SEGURANÇA: Garante arrays básicos
    if (!data.ingredients) data.ingredients = [];
    if (!data.products) data.products = [];
    if (!data.menuCategories || data.menuCategories.length === 0) {
      data.menuCategories = [...INITIAL_MENU_CATEGORIES];
    }

    // 3. RECUPERAÇÃO DE PRODUTOS: Garante categoria e ordem em todos
    data.products = data.products.map((p, idx) => ({
      ...p,
      category: p.category || 'Geral',
      order: p.order !== undefined ? p.order : idx
    }));

    // 4. SINCRONIZAÇÃO DE SEÇÕES: Se existe um produto com uma categoria que não está na lista, cria a seção.
    const allUsedCategories = Array.from(new Set(data.products.map(p => p.category)));
    allUsedCategories.forEach(catName => {
        const exists = data.menuCategories!.some(mc => mc.name === catName);
        if (!exists) {
            data.menuCategories!.push({
                id: 'mig_' + Math.random().toString(36).substr(2, 4),
                name: catName,
                order: data.menuCategories!.length
            });
        }
    });

    return data;
  });

  const isFirstRender = useRef(true);
  useEffect(() => {
    if (isFirstRender.current) {
      isFirstRender.current = false;
      return;
    }
    if (onStateChange) onStateChange(state);
  }, [state, onStateChange]);

  const addIngredient = (ing: Ingredient) => setState(s => ({ ...s, ingredients: [...s.ingredients, ing] }));
  const updateIngredient = (id: string, data: Partial<Ingredient>) => {
    setState(s => ({ ...s, ingredients: s.ingredients.map(i => i.id === id ? { ...i, ...data } : i) }));
  };
  const deleteIngredient = (id: string) => setState(s => ({ ...s, ingredients: s.ingredients.filter(i => i.id !== id) }));

  const addProduct = (prod: Product) => setState(s => {
      const sameCat = s.products.filter(p => p.category === prod.category);
      return { ...s, products: [...s.products, { ...prod, order: sameCat.length }] };
  });

  const updateProduct = (id: string, data: Partial<Product>) => {
    setState(s => ({ ...s, products: s.products.map(p => p.id === id ? { ...p, ...data } : p) }));
  };

  const deleteProduct = (id: string) => setState(s => ({ ...s, products: s.products.filter(p => p.id !== id) }));

  const reorderProduct = (id: string, direction: 'up' | 'down') => {
    setState(s => {
      const product = s.products.find(p => p.id === id);
      if (!product) return s;
      const sameCat = s.products.filter(p => p.category === product.category).sort((a, b) => (a.order || 0) - (b.order || 0));
      const idx = sameCat.findIndex(p => p.id === id);
      if (direction === 'up' && idx === 0) return s;
      if (direction === 'down' && idx === sameCat.length - 1) return s;
      const target = sameCat[direction === 'up' ? idx - 1 : idx + 1];
      return { ...s, products: s.products.map(p => {
        if (p.id === product.id) return { ...p, order: target.order };
        if (p.id === target.id) return { ...p, order: product.order };
        return p;
      })};
    });
  };

  const addMenuCategory = (name: string) => setState(s => ({
      ...s, menuCategories: [...(s.menuCategories || []), { id: Date.now().toString(), name, order: (s.menuCategories || []).length }]
  }));

  const deleteMenuCategory = (id: string) => setState(s => {
      const cat = s.menuCategories?.find(c => c.id === id);
      return { 
          ...s, 
          products: s.products.map(p => p.category === cat?.name ? { ...p, category: 'Geral' } : p),
          menuCategories: s.menuCategories?.filter(c => c.id !== id) 
      };
  });

  const reorderMenuCategory = (id: string, direction: 'up' | 'down') => {
    setState(s => {
        const sorted = [...(s.menuCategories || [])].sort((a,b) => a.order - b.order);
        const idx = sorted.findIndex(c => c.id === id);
        if ((direction === 'up' && idx === 0) || (direction === 'down' && idx === sorted.length - 1)) return s;
        const target = sorted[direction === 'up' ? idx - 1 : idx + 1];
        return { ...s, menuCategories: s.menuCategories?.map(c => {
            if (c.id === id) return { ...c, order: target.order };
            if (c.id === target.id) return { ...c, order: sorted[idx].order };
            return c;
        })};
    });
  };

  const addCombo = (combo: Combo) => setState(s => ({ ...s, combos: [...s.combos, combo] }));
  const updateCombo = (id: string, data: Partial<Combo>) => {
    setState(s => ({ ...s, combos: s.combos.map(c => c.id === id ? { ...c, ...data } : c) }));
  };
  const deleteCombo = (id: string) => setState(s => ({ ...s, combos: s.combos.filter(c => c.id !== id) }));

  const addExpense = (exp: Expense) => setState(s => ({ ...s, expenses: [...s.expenses, exp] }));
  const updateExpense = (id: string, data: Partial<Expense>) => {
    setState(s => ({ ...s, expenses: s.expenses.map(e => e.id === id ? { ...e, ...data } : e) }));
  };
  const addExpenseWithInstallments = (baseExp: Omit<Expense, 'id' | 'installment'>, installments: number) => {
    const newExpenses: Expense[] = [];
    const groupId = Math.random().toString(36).substr(2, 9);
    let [year, month] = baseExp.month.split('-').map(Number);
    for (let i = 1; i <= installments; i++) {
      const mStr = `${year}-${month.toString().padStart(2, '0')}`;
      newExpenses.push({ ...baseExp, id: Math.random().toString(36).substr(2, 9), month: mStr, installment: { current: i, total: installments, id: groupId } });
      month++; if (month > 12) { month = 1; year++; }
    }
    setState(s => ({ ...s, expenses: [...s.expenses, ...newExpenses] }));
  };

  const addCategory = (cat: Category) => setState(s => ({ ...s, categories: [...s.categories, cat] }));
  const deleteCategory = (id: string) => setState(s => ({ ...s, categories: s.categories.filter(c => c.id !== id) }));
  const addSupplier = (sup: Supplier) => setState(s => ({ ...s, suppliers: [...s.suppliers, sup] }));
  const deleteSupplier = (id: string) => setState(s => ({ ...s, suppliers: s.suppliers.filter(s => s.id !== id) }));
  const updateCfi = (cfi: Partial<CfiConfig>) => setState(s => ({ ...s, cfi: { ...s.cfi, ...cfi } }));
  const updatePlatformConfig = (cfg: Partial<PlatformConfig>) => setState(s => ({ ...s, platformConfig: { ...s.platformConfig, ...cfg } }));
  const updateMonthlyRevenue = (data: MonthlyData[]) => setState(s => ({ ...s, monthlyRevenue: data }));
  const updateStoreInfo = (info: Partial<StoreInfo>) => setState(s => ({ ...s, storeInfo: { ...s.storeInfo, ...info } }));
  const setFixedCostMode = (mode: FixedCostMode) => setState(s => ({ ...s, fixedCostMode: mode }));

  const getIngredientRealCost = (ing: Ingredient) => {
    if (!ing.packageQuantity || ing.packageQuantity <= 0) return 0;
    return ing.price / (ing.packageQuantity * (1 - (ing.lossPercent / 100)));
  };

  const getProductCMV = (prod: Product) => {
    return prod.ingredients.reduce((total, item) => {
      const ing = state.ingredients.find(i => i.id === item.ingredientId);
      return total + (ing ? getIngredientRealCost(ing) * item.quantity : 0);
    }, 0);
  };

  const calculateFixedCostPercent = () => {
    const totalCost = state.expenses.reduce((s, e) => s + e.value, 0);
    const totalRev = state.monthlyRevenue.reduce((s, r) => s + r.revenue, 0);
    return totalRev > 0 ? (totalCost / totalRev) * 100 : 0;
  };

  const calculateTotalCfiPercent = () => {
    return calculateFixedCostPercent() + (state.cfi.debitTax + state.cfi.creditTax)/2 + state.cfi.tax + state.cfi.royalties + state.cfi.marketing + state.cfi.voucherTax;
  };

  const getSortedProducts = () => {
      const cats = state.menuCategories || INITIAL_MENU_CATEGORIES;
      const catOrderMap: Record<string, number> = {};
      cats.forEach(c => catOrderMap[c.name] = c.order);
      return [...state.products].sort((a, b) => (catOrderMap[a.category] ?? 99) - (catOrderMap[b.category] ?? 99) || (a.order || 0) - (b.order || 0));
  };

  return (
    <AppContext.Provider value={{
      ...state,
      menuCategories: state.menuCategories || INITIAL_MENU_CATEGORIES,
      addIngredient, updateIngredient, deleteIngredient,
      addProduct, updateProduct, deleteProduct, reorderProduct,
      addMenuCategory, deleteMenuCategory, reorderMenuCategory,
      addCombo, updateCombo, deleteCombo,
      addExpense, updateExpense, addExpenseWithInstallments,
      addCategory, deleteCategory,
      addSupplier, deleteSupplier,
      updateCfi, updatePlatformConfig, updateMonthlyRevenue, updateStoreInfo,
      setFixedCostMode,
      getIngredientRealCost, getProductCMV, calculateFixedCostPercent, calculateTotalCfiPercent,
      getSortedProducts
    }}>
      {children}
    </AppContext.Provider>
  );
};

export const useApp = () => {
  const context = useContext(AppContext);
  if (context === undefined) throw new Error('useApp deve ser usado dentro de um AppProvider');
  return context;
};

import React, { useState, useEffect, useLayoutEffect } from 'react';
import { AppProvider } from './context/AppContext';
import Sidebar from './components/Sidebar';
import Dashboard from './pages/Dashboard';
import Ingredients from './pages/Ingredients';
import Products from './pages/Products';
import Pricing from './pages/Pricing';
import Expenses from './pages/Expenses';
import Dna from './pages/Dna';
import FinancialCategories from './pages/FinancialCategories';
import Billing from './pages/Billing';
import Profit from './pages/Profit';
import Combos from './pages/Combos';
import StoreList from './pages/StoreList';
import Help from './pages/Help';
import { StoreInfo, GlobalState } from './types';
import { INITIAL_STATE, EMPTY_STATE, BACKGROUND_PALETTE } from './constants';

// CHAVES ORIGINAIS DO SISTEMA - ONDE SEUS DADOS ESTÃO SALVOS
const STORAGE_KEY_DATA = 'lucro_facil_pro_data';
const STORAGE_KEY_STORES = 'lucro_facil_pro_stores';
const STORAGE_KEY_LAST_BACKUP = 'lucro_facil_last_backup_date';

const App: React.FC = () => {
  const [selectedStoreId, setSelectedStoreId] = useState<string | null>(null);

  const [bgColor, setBgColor] = useState(() => {
    return localStorage.getItem('app_bg_color') || BACKGROUND_PALETTE[0].color;
  });

  const [lastBackupDate, setLastBackupDate] = useState<string | null>(() => {
    return localStorage.getItem(STORAGE_KEY_LAST_BACKUP);
  });

  useLayoutEffect(() => {
    const root = window.document.documentElement;
    const selectedPalette = BACKGROUND_PALETTE.find(p => p.color === bgColor) || BACKGROUND_PALETTE[0];
    if (selectedPalette.mode === 'dark') root.classList.add('dark');
    else root.classList.remove('dark');
    root.style.setProperty('--app-bg', bgColor);
    localStorage.setItem('app_bg_color', bgColor);
  }, [bgColor]);

  // Carregar Lojas
  const [stores, setStores] = useState<StoreInfo[]>(() => {
    const saved = localStorage.getItem(STORAGE_KEY_STORES);
    if (saved) return JSON.parse(saved);
    return [{ id: '1', name: 'Minha Hamburgueria', address: '' }];
  });

  // Carregar Dados das Lojas (Produtos, Insumos, etc)
  const [storesData, setStoresData] = useState<Record<string, GlobalState>>(() => {
    const saved = localStorage.getItem(STORAGE_KEY_DATA);
    if (saved) return JSON.parse(saved);
    return { '1': INITIAL_STATE };
  });

  // SALVAMENTO AUTOMÁTICO
  useEffect(() => {
    localStorage.setItem(STORAGE_KEY_STORES, JSON.stringify(stores));
    localStorage.setItem(STORAGE_KEY_DATA, JSON.stringify(storesData));
  }, [stores, storesData]);

  const handleBackup = () => {
    const backupData = { stores, storesData, date: new Date().toISOString() };
    const blob = new Blob([JSON.stringify(backupData, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `Backup_LucroFacil_${new Date().toISOString().split('T')[0]}.json`;
    a.click();
    setLastBackupDate(new Date().toISOString());
    localStorage.setItem(STORAGE_KEY_LAST_BACKUP, new Date().toISOString());
  };

  const handleRestore = (file: File) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const parsed = JSON.parse(e.target?.result as string);
        if (parsed.stores && parsed.storesData) {
          if (confirm('Restaurar backup? Isso apagará os dados atuais.')) {
            setStores(parsed.stores);
            setStoresData(parsed.storesData);
            window.location.reload();
          }
        }
      } catch (err) { alert('Arquivo inválido.'); }
    };
    reader.readAsText(file);
  };

  const handleStateChange = (newState: GlobalState) => {
    if (selectedStoreId) {
      setStoresData(prev => ({ ...prev, [selectedStoreId]: newState }));
    }
  };

  if (!selectedStoreId) {
    return (
      <StoreList 
        stores={stores}
        onSelectStore={setSelectedStoreId} 
        onAddStore={(s) => {
          const id = Date.now().toString();
          setStores([...stores, { ...s, id }]);
          setStoresData({ ...storesData, [id]: { ...EMPTY_STATE, storeInfo: { ...s, id } } });
        }}
        onUpdateStore={(s) => setStores(stores.map(st => st.id === s.id ? s : st))}
        onDeleteStore={(id) => {
           if(confirm('Excluir loja?')) {
             setStores(stores.filter(s => s.id !== id));
             const newData = { ...storesData }; delete newData[id]; setStoresData(newData);
           }
        }}
      />
    );
  }

  const currentStoreData = storesData[selectedStoreId];

  return (
    <AppProvider storeId={selectedStoreId} initialData={currentStoreData} onStateChange={handleStateChange}>
      <AppContent 
        onLogout={() => setSelectedStoreId(null)} 
        bgColor={bgColor} 
        onBgColorChange={setBgColor}
        onBackup={handleBackup}
        onRestore={handleRestore}
        lastBackupDate={lastBackupDate}
      />
    </AppProvider>
  );
};

const AppContent: React.FC<any> = ({ onLogout, bgColor, onBgColorChange, onBackup, onRestore, lastBackupDate }) => {
  const [activeTab, setActiveTab] = useState('dashboard');
  const renderContent = () => {
    switch (activeTab) {
      case 'dashboard': return <Dashboard />;
      case 'ingredients': return <Ingredients />;
      case 'products': return <Products />;
      case 'pricing': return <Pricing />;
      case 'expenses': return <Expenses />;
      case 'dna': return <Dna />;
      case 'categories': return <FinancialCategories />;
      case 'billing': return <Billing />;
      case 'profit': return <Profit />;
      case 'combos': return <Combos />;
      case 'help': return <Help />;
      default: return <Dashboard />;
    }
  };

  return (
    <div className="flex min-h-screen">
      <Sidebar activeTab={activeTab} setActiveTab={setActiveTab} onLogout={onLogout} bgColor={bgColor} onBgColorChange={onBgColorChange} onBackup={onBackup} onRestore={onRestore} lastBackupDate={lastBackupDate} />
      <main className="flex-1 ml-64 p-8">{renderContent()}</main>
    </div>
  );
};

export default App;

import React, { createContext, useContext, useState, ReactNode, useEffect, useRef } from 'react';
import { GlobalState, Ingredient, Product, Expense, MonthlyData, CfiConfig, PlatformConfig, Category, Supplier, FixedCostMode, Combo, StoreInfo } from '../types';
import { INITIAL_STATE, EMPTY_STATE } from '../constants';

interface AppContextType extends GlobalState {
  addIngredient: (ing: Ingredient) => void;
  updateIngredient: (id: string, ing: Partial<Ingredient>) => void;
  deleteIngredient: (id: string) => void;
  addProduct: (prod: Product) => void;
  updateProduct: (id: string, prod: Partial<Product>) => void;
  deleteProduct: (id: string) => void;
  addCombo: (combo: Combo) => void;
  updateCombo: (id: string, combo: Partial<Combo>) => void;
  deleteCombo: (id: string) => void;
  addExpense: (exp: Expense) => void;
  updateExpense: (id: string, exp: Partial<Expense>) => void;
  addExpenseWithInstallments: (baseExp: Omit<Expense, 'id' | 'installment'>, installments: number) => void;
  addCategory: (cat: Category) => void;
  deleteCategory: (id: string) => void;
  addSupplier: (sup: Supplier) => void;
  deleteSupplier: (id: string) => void;
  updateCfi: (cfi: Partial<CfiConfig>) => void;
  updatePlatformConfig: (cfg: Partial<PlatformConfig>) => void;
  updateMonthlyRevenue: (data: MonthlyData[]) => void;
  updateStoreInfo: (info: Partial<StoreInfo>) => void;
  setFixedCostMode: (mode: FixedCostMode) => void;
  getIngredientRealCost: (ing: Ingredient) => number;
  getProductCMV: (prod: Product) => number;
  calculateFixedCostPercent: () => number;
  calculateTotalCfiPercent: () => number;
  getSortedProducts: () => Product[];
}

const AppContext = createContext<AppContextType | undefined>(undefined);

export const AppProvider: React.FC<{ children: ReactNode; storeId: string; initialData?: GlobalState; onStateChange?: (newState: GlobalState) => void; }> = ({ children, storeId, initialData, onStateChange }) => {
  const [state, setState] = useState<GlobalState>(() => initialData || (storeId === '1' ? INITIAL_STATE : EMPTY_STATE));

  const isFirstRender = useRef(true);
  useEffect(() => {
    if (isFirstRender.current) { isFirstRender.current = false; return; }
    if (onStateChange) onStateChange(state);
  }, [state]);

  const addIngredient = (ing: Ingredient) => setState(s => ({ ...s, ingredients: [...s.ingredients, ing] }));
  const updateIngredient = (id: string, data: Partial<Ingredient>) => setState(s => ({ ...s, ingredients: s.ingredients.map(i => i.id === id ? { ...i, ...data } : i) }));
  const deleteIngredient = (id: string) => setState(s => ({ ...s, ingredients: s.ingredients.filter(i => i.id !== id) }));

  const addProduct = (prod: Product) => setState(s => ({ ...s, products: [...s.products, prod] }));
  const updateProduct = (id: string, data: Partial<Product>) => setState(s => ({ ...s, products: s.products.map(p => p.id === id ? { ...p, ...data } : p) }));
  const deleteProduct = (id: string) => setState(s => ({ ...s, products: s.products.filter(p => p.id !== id) }));

  const addCombo = (combo: Combo) => setState(s => ({ ...s, combos: [...s.combos, combo] }));
  const updateCombo = (id: string, data: Partial<Combo>) => setState(s => ({ ...s, combos: s.combos.map(c => c.id === id ? { ...c, ...data } : c) }));
  const deleteCombo = (id: string) => setState(s => ({ ...s, combos: s.combos.filter(c => c.id !== id) }));

  const addExpense = (exp: Expense) => setState(s => ({ ...s, expenses: [...s.expenses, exp] }));
  const updateExpense = (id: string, data: Partial<Expense>) => setState(s => ({ ...s, expenses: s.expenses.map(e => e.id === id ? { ...e, ...data } : e) }));
  const addExpenseWithInstallments = (baseExp: any, installments: number) => {
      const news: Expense[] = [];
      for (let i = 1; i <= installments; i++) news.push({ ...baseExp, id: Math.random().toString(36).substr(2, 9) });
      setState(s => ({ ...s, expenses: [...s.expenses, ...news] }));
  };

  const addCategory = (cat: Category) => setState(s => ({ ...s, categories: [...s.categories, cat] }));
  const deleteCategory = (id: string) => setState(s => ({ ...s, categories: s.categories.filter(c => c.id !== id) }));
  const addSupplier = (sup: Supplier) => setState(s => ({ ...s, suppliers: [...s.suppliers, sup] }));
  const deleteSupplier = (id: string) => setState(s => ({ ...s, suppliers: s.suppliers.filter(s => s.id !== id) }));
  const updateCfi = (cfi: Partial<CfiConfig>) => setState(s => ({ ...s, cfi: { ...s.cfi, ...cfi } }));
  const updatePlatformConfig = (cfg: Partial<PlatformConfig>) => setState(s => ({ ...s, platformConfig: { ...s.platformConfig, ...cfg } }));
  const updateMonthlyRevenue = (data: MonthlyData[]) => setState(s => ({ ...s, monthlyRevenue: data }));
  const updateStoreInfo = (info: Partial<StoreInfo>) => setState(s => ({ ...s, storeInfo: { ...s.storeInfo, ...info } }));
  const setFixedCostMode = (mode: FixedCostMode) => setState(s => ({ ...s, fixedCostMode: mode }));

  const getIngredientRealCost = (ing: Ingredient) => {
    if (!ing.packageQuantity || ing.packageQuantity <= 0) return 0;
    return ing.price / (ing.packageQuantity * (1 - (ing.lossPercent / 100)));
  };

  const getProductCMV = (prod: Product) => {
    return prod.ingredients.reduce((t, item) => {
      const ing = state.ingredients.find(i => i.id === item.ingredientId);
      return t + (ing ? getIngredientRealCost(ing) * item.quantity : 0);
    }, 0);
  };

  const calculateFixedCostPercent = () => {
    const totalCost = state.expenses.reduce((s, e) => s + e.value, 0);
    const totalRev = state.monthlyRevenue.reduce((s, r) => s + r.revenue, 0);
    return totalRev > 0 ? (totalCost / totalRev) * 100 : 0;
  };

  const calculateTotalCfiPercent = () => {
    return calculateFixedCostPercent() + (state.cfi.debitTax + state.cfi.creditTax)/2 + state.cfi.tax + state.cfi.royalties + state.cfi.marketing + state.cfi.voucherTax;
  };

  const getSortedProducts = () => [...state.products].sort((a, b) => a.name.localeCompare(b.name));

  return (
    <AppContext.Provider value={{
      ...state,
      addIngredient, updateIngredient, deleteIngredient,
      addProduct, updateProduct, deleteProduct,
      addCombo, updateCombo, deleteCombo,
      addExpense, updateExpense, addExpenseWithInstallments,
      addCategory, deleteCategory,
      addSupplier, deleteSupplier,
      updateCfi, updatePlatformConfig, updateMonthlyRevenue, updateStoreInfo,
      setFixedCostMode,
      getIngredientRealCost, getProductCMV, calculateFixedCostPercent, calculateTotalCfiPercent,
      getSortedProducts
    }}>
      {children}
    </AppContext.Provider>
  );
};

