                     <button onClick={handleSaveProduct} className="px-8 py-3 rounded-xl bg-brand-red hover:bg-red-700 text-white font-bold shadow-xl transition transform active:scale-95">SALVAR ALTERAÇÕES</button>
                  </div>
               </div>
            </div>
         </div>
       )}
    </div>
  );
};

