                <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-500" size={16} />
                <input type="text" placeholder="Buscar..." value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} className="w-full bg-white dark:bg-gray-900 border border-gray-200 dark:border-gray-800 text-gray-900 dark:text-white rounded-lg pl-10 pr-4 py-2 text-sm focus:ring-2 focus:ring-brand-red outline-none shadow-sm" />
            </div>
            <button onClick={() => setIsCatModalOpen(true)} className="bg-gray-100 dark:bg-gray-800 text-gray-700 dark:text-gray-300 p-2.5 rounded-lg border border-gray-200 dark:border-gray-700 hover:bg-gray-200 transition" title="Categorias"><ListOrdered size={20} /></button>
            <button onClick={() => { setEditingProduct(null); setProdName(''); setProdCategory(sortedCategories[0]?.name || 'Geral'); setIsModalOpen(true); }} className="bg-brand-red hover:bg-red-700 text-white px-4 py-2.5 rounded-lg flex items-center gap-2 font-bold transition shadow-lg"><Plus size={18} /> NOVO ITEM</button>
          </div>
       </div>

       {Object.entries(groupedProducts).map(([catName, items]) => {
           if (items.length === 0 && (catName !== 'Outros' || !searchTerm)) return null;
           return (
               <div key={catName} className="space-y-3">
                   <div className="flex items-center gap-3 border-b border-gray-200 dark:border-gray-800 pb-2">
                       <h3 className="text-lg font-black text-gray-900 dark:text-white uppercase tracking-wider">{catName}</h3>
                       <span className="text-[10px] bg-gray-100 dark:bg-gray-800 text-gray-500 px-2 py-0.5 rounded-full font-bold">{items.length}</span>
                   </div>
                   <div className="bg-white dark:bg-gray-900 border border-gray-200 dark:border-gray-800 rounded-xl overflow-hidden shadow-sm">
                       <table className="w-full text-left">
                           <thead className="bg-gray-50 dark:bg-[#0f111a] text-gray-400 text-[10px] uppercase font-bold tracking-wider">
                               <tr>
                                   <th className="px-6 py-3 w-16 text-center">Ordem</th>
                                   <th className="px-6 py-3">Produto</th>
                                   <th className="px-6 py-3 text-right">CMV Est.</th>
                                   <th className="px-6 py-3 text-right">Ação</th>
                               </tr>
                           </thead>
                           <tbody className="divide-y divide-gray-100 dark:divide-gray-800 text-sm">
                               {items.map((prod, pIdx) => (
                                   <tr key={prod.id} className="hover:bg-gray-50 dark:hover:bg-gray-800/50 transition">
                                       <td className="px-6 py-3 text-center">
