                                               <button onClick={() => reorderProduct(prod.id, 'up')} disabled={pIdx === 0} className="p-1 text-brand-red disabled:opacity-10"><ChevronUp size={14}/></button>
                                               <button onClick={() => reorderProduct(prod.id, 'down')} disabled={pIdx === items.length - 1} className="p-1 text-brand-red disabled:opacity-10"><ChevronDown size={14}/></button>
                                           </div>
                                       </td>
