                                    return (
                                       <tr key={idx} className="hover:bg-gray-50 dark:hover:bg-gray-900/50">
                                          <td className="px-4 py-3 font-medium dark:text-white">{ing.name}</td>
                                          <td className="px-4 py-3 text-center text-xs text-gray-500">{ing.unit}</td>
