import React, { useState, useRef } from 'react';
import { Plus, Store, ArrowRight, MapPin, Edit2, Upload, X, Trash2, AlertTriangle, Tags, TrendingUp, DownloadCloud } from 'lucide-react';
import { StoreInfo } from '../types';

interface StoreListProps {
  stores: StoreInfo[];
  onSelectStore: (storeId: string) => void;
  onAddStore: (store: StoreInfo) => void;
  onUpdateStore: (store: StoreInfo) => void;
  onDeleteStore?: (storeId: string) => void;
  onRestore: (file: File) => void;
}

const StoreList: React.FC<StoreListProps> = ({ stores, onSelectStore, onAddStore, onUpdateStore, onDeleteStore, onRestore }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingStore, setEditingStore] = useState<StoreInfo | null>(null);
  const [storeToDelete, setStoreToDelete] = useState<StoreInfo | null>(null);

  const [name, setName] = useState('');
  const [address, setAddress] = useState('');
  const [logo, setLogo] = useState('');

  const fileInputRef = useRef<HTMLInputElement>(null);
  const restoreInputRef = useRef<HTMLInputElement>(null);

  const handleOpenModal = (store?: StoreInfo) => {
    if (store) {
      setEditingStore(store); setName(store.name); setAddress(store.address || ''); setLogo(store.logo || '');
    } else {
      setEditingStore(null); setName(''); setAddress(''); setLogo('');
    }
    setIsModalOpen(true);
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => setLogo(reader.result as string);
      reader.readAsDataURL(file);
    }
  };

  const handleRestoreFile = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) onRestore(file);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!name) return;
    const storeData: StoreInfo = { id: editingStore?.id, name, address, logo };
    if (editingStore) onUpdateStore(storeData);
    else onAddStore(storeData);
    setIsModalOpen(false);
  };

  return (
    <div className="min-h-screen bg-[var(--app-bg)] flex flex-col items-center justify-center p-8 animate-fade-in relative overflow-hidden transition-colors duration-500">

      <div className="max-w-6xl w-full space-y-10 relative z-10">

        <div className="flex flex-col items-center justify-center text-center space-y-6">
            <div className="relative w-24 h-24 bg-white dark:bg-gray-900 rounded-2xl border border-gray-200 dark:border-gray-800 flex items-center justify-center shadow-2xl">
                <TrendingUp size={48} className="text-brand-red" />
            </div>
            <div className="space-y-2">
                 <h1 className="text-4xl md:text-6xl font-extrabold text-gray-900 dark:text-white tracking-tight leading-none uppercase">Lucro Fácil Pro</h1>
                 <p className="text-lg md:text-xl text-gray-500 dark:text-gray-400 font-medium">Selecione sua unidade ou restaure seus dados abaixo.</p>
            </div>
        </div>

        {/* BOTÃO DE RESTAURAÇÃO DE EMERGÊNCIA */}
        <div className="max-w-md mx-auto bg-brand-red/10 border-2 border-dashed border-brand-red p-8 rounded-2xl text-center space-y-4 shadow-2xl">
            <DownloadCloud className="mx-auto text-brand-red animate-bounce" size={48} />
            <h3 className="text-gray-900 dark:text-white font-black uppercase text-xl">Recuperar Dados</h3>
            <p className="text-gray-600 dark:text-gray-400 text-sm">Seus produtos não apareceram? Clique abaixo e selecione o arquivo de <strong>Backup (.json)</strong> que você salvou no PC.</p>
            <button 
                onClick={() => restoreInputRef.current?.click()}
                className="w-full bg-brand-red hover:bg-red-700 text-white font-black py-4 rounded-xl flex items-center justify-center gap-2 shadow-xl transition transform active:scale-95"
            >
                <Upload size={20} /> RESTAURAR BACKUP AGORA
            </button>
            <input type="file" ref={restoreInputRef} className="hidden" accept=".json" onChange={handleRestoreFile} />
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {stores.map(store => (
                <div 
                    key={store.id}
                    className="bg-white dark:bg-gray-900 border border-gray-200 dark:border-gray-800 p-6 rounded-2xl text-left hover:border-brand-red hover:shadow-2xl transition-all duration-300 group relative flex flex-col h-full cursor-pointer"
                    onClick={() => onSelectStore(store.id!)}
                >
                    <div className="absolute top-3 right-3 flex gap-2 z-20">
                        <button onClick={(e) => { e.stopPropagation(); handleOpenModal(store); }} className="text-gray-400 hover:text-gray-900 dark:hover:text-white p-2 rounded-full"><Edit2 size={14} /></button>
                        {onDeleteStore && <button onClick={(e) => { e.stopPropagation(); setStoreToDelete(store); }} className="text-gray-400 hover:text-red-500 p-2 rounded-full"><Trash2 size={14} /></button>}
                    </div>
                    <div className="w-12 h-12 bg-gray-100 dark:bg-gray-800 rounded-xl flex items-center justify-center mb-4 border border-gray-200 dark:border-gray-700 overflow-hidden">
                        {store.logo ? <img src={store.logo} className="w-full h-full object-cover" /> : <Store size={20} className="text-brand-red" />}
                    </div>
                    <h3 className="text-lg font-bold text-gray-900 dark:text-white mb-1 truncate">{store.name}</h3>
                    <div className="flex items-center gap-2 text-xs text-gray-500 mb-4"><MapPin size={12}/> {store.address || 'Sem endereço'}</div>
                    <div className="pt-3 border-t border-gray-100 dark:border-gray-800 mt-auto flex items-center justify-between text-xs font-bold text-brand-red">
                        <span>ENTRAR NO SISTEMA</span> <ArrowRight size={14} />
                    </div>
                </div>
            ))}
        </div>
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 bg-black/80 backdrop-blur-sm flex items-center justify-center z-50 p-4">
            <div className="bg-white dark:bg-gray-900 border border-gray-200 dark:border-gray-800 rounded-xl shadow-2xl w-full max-w-md p-6 space-y-4">
                <h3 className="text-xl font-bold dark:text-white">{editingStore ? 'Editar Loja' : 'Nova Loja'}</h3>
                <div>
                    <label className="text-[10px] text-gray-500 uppercase font-bold block mb-1">Nome da Loja</label>
                    <input type="text" value={name} onChange={e => setName(e.target.value)} className="w-full bg-gray-50 dark:bg-gray-800 border dark:border-gray-700 rounded-lg p-3 dark:text-white outline-none focus:border-brand-red" />
                </div>
                <div className="pt-2 flex gap-3">
                    <button onClick={() => setIsModalOpen(false)} className="flex-1 py-3 bg-gray-200 dark:bg-gray-800 text-gray-700 dark:text-white font-bold rounded-lg">Cancelar</button>
                    <button onClick={handleSubmit} className="flex-1 py-3 bg-brand-red text-white font-bold rounded-lg shadow-lg">Salvar</button>
                </div>
            </div>
        </div>
      )}

      {storeToDelete && (
          <div className="fixed inset-0 bg-black/80 backdrop-blur-sm flex items-center justify-center z-50 p-4">
              <div className="bg-white dark:bg-gray-900 p-6 rounded-xl max-w-md w-full shadow-2xl text-center">
                  <AlertTriangle size={48} className="text-red-500 mx-auto mb-4" />
                  <h3 className="text-xl font-bold dark:text-white mb-2">Excluir Loja?</h3>
                  <p className="text-gray-500 mb-6">Todos os dados desta unidade serão apagados.</p>
                  <div className="flex gap-4">
                      <button onClick={() => setStoreToDelete(null)} className="flex-1 py-3 bg-gray-200 dark:bg-gray-800 rounded-lg">Não</button>
                      <button onClick={() => { onDeleteStore!(storeToDelete.id!); setStoreToDelete(null); }} className="flex-1 py-3 bg-red-600 text-white rounded-lg">Sim, Excluir</button>
                  </div>
              </div>
          </div>
      )}
    </div>
  );
};

