import React, { useState, useEffect, useLayoutEffect } from 'react';
import { AppProvider } from './context/AppContext';
import Sidebar from './components/Sidebar';
import Dashboard from './pages/Dashboard';
import Ingredients from './pages/Ingredients';
import Products from './pages/Products';
import Pricing from './pages/Pricing';
import Expenses from './pages/Expenses';
import Dna from './pages/Dna';
import FinancialCategories from './pages/FinancialCategories';
import Billing from './pages/Billing';
import Profit from './pages/Profit';
import Combos from './pages/Combos';
import StoreList from './pages/StoreList';
import Help from './pages/Help';
import { StoreInfo, GlobalState } from './types';
import { INITIAL_STATE, EMPTY_STATE, BACKGROUND_PALETTE } from './constants';

const STORAGE_KEY_DATA = 'lucro_facil_pro_data';
const STORAGE_KEY_STORES = 'lucro_facil_pro_stores';
const STORAGE_KEY_LAST_BACKUP = 'lucro_facil_last_backup_date';

const App: React.FC = () => {
  const [selectedStoreId, setSelectedStoreId] = useState<string | null>(null);
  const [bgColor, setBgColor] = useState(() => localStorage.getItem('app_bg_color') || BACKGROUND_PALETTE[0].color);
  const [lastBackupDate, setLastBackupDate] = useState<string | null>(() => localStorage.getItem(STORAGE_KEY_LAST_BACKUP));

  const [stores, setStores] = useState<StoreInfo[]>(() => {
    const saved = localStorage.getItem(STORAGE_KEY_STORES);
    return saved ? JSON.parse(saved) : [{ id: '1', name: 'Minha Hamburgueria', address: '' }];
  });

  const [storesData, setStoresData] = useState<Record<string, GlobalState>>(() => {
    const saved = localStorage.getItem(STORAGE_KEY_DATA);
    return saved ? JSON.parse(saved) : { '1': INITIAL_STATE };
  });

  useLayoutEffect(() => {
    const root = window.document.documentElement;
    const selectedPalette = BACKGROUND_PALETTE.find(p => p.color === bgColor) || BACKGROUND_PALETTE[0];
    if (selectedPalette.mode === 'dark') root.classList.add('dark');
    else root.classList.remove('dark');
    root.style.setProperty('--app-bg', bgColor);
    localStorage.setItem('app_bg_color', bgColor);
  }, [bgColor]);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY_STORES, JSON.stringify(stores));
    localStorage.setItem(STORAGE_KEY_DATA, JSON.stringify(storesData));
  }, [stores, storesData]);

  const handleBackup = () => {
    const backupData = { stores, storesData, date: new Date().toISOString() };
    const blob = new Blob([JSON.stringify(backupData, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `Backup_LucroFacil_${new Date().toISOString().split('T')[0]}.json`;
    a.click();
    setLastBackupDate(new Date().toISOString());
    localStorage.setItem(STORAGE_KEY_LAST_BACKUP, new Date().toISOString());
  };

  const handleRestore = (file: File) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const parsed = JSON.parse(e.target?.result as string);

        // FORMATO MULTI-LOJA
        if (parsed.stores && parsed.storesData) {
          if (confirm('RESTAURAR BACKUP? Todos os dados atuais serão substituídos pelo arquivo.')) {
            localStorage.clear(); 
            setStores(parsed.stores);
            setStoresData(parsed.storesData);
            setTimeout(() => {
              localStorage.setItem(STORAGE_KEY_STORES, JSON.stringify(parsed.stores));
              localStorage.setItem(STORAGE_KEY_DATA, JSON.stringify(parsed.storesData));
              window.location.reload();
            }, 200);
          }
        } 
        // FORMATO LEGADO (Loja Única)
        else if (parsed.products || parsed.ingredients) {
          if (confirm('BACKUP ANTIGO DETECTADO. Deseja importar esses dados como uma nova loja?')) {
            const newId = Date.now().toString();
            const newStore = { id: newId, name: parsed.storeInfo?.name || 'Restaurado Legado', address: parsed.storeInfo?.address || '' };
            const newData = { ...storesData, [newId]: { ...EMPTY_STATE, ...parsed } };
            setStores([...stores, newStore]);
            setStoresData(newData);
            alert('Dados importados com sucesso! Selecione a nova loja na lista.');
          }
        } else {
          alert('Arquivo de backup inválido.');
        }
      } catch (err) { alert('Erro ao processar arquivo.'); }
    };
    reader.readAsText(file);
  };

  const handleStateChange = (newState: GlobalState) => {
    if (selectedStoreId) {
      setStoresData(prev => ({ ...prev, [selectedStoreId]: newState }));
    }
  };

  if (!selectedStoreId) {
    return (
      <StoreList 
        stores={stores}
        onSelectStore={setSelectedStoreId} 
        onAddStore={(s) => {
          const id = Date.now().toString();
          setStores([...stores, { ...s, id }]);
          setStoresData({ ...storesData, [id]: { ...EMPTY_STATE, storeInfo: { ...s, id } } });
        }}
        onUpdateStore={(s) => setStores(stores.map(st => st.id === s.id ? s : st))}
        onDeleteStore={(id) => {
          if(confirm('Excluir unidade?')) {
            const newStores = stores.filter(s => s.id !== id);
            if (newStores.length === 0) return alert('Você precisa de pelo menos uma loja.');
            setStores(newStores);
            const newData = { ...storesData }; delete newData[id]; setStoresData(newData);
          }
        }}
        onRestore={handleRestore}
      />
    );
  }

  return (
    <AppProvider storeId={selectedStoreId} initialData={storesData[selectedStoreId]} onStateChange={handleStateChange}>
      <AppContent 
        onLogout={() => setSelectedStoreId(null)} 
        bgColor={bgColor} 
        onBgColorChange={setBgColor}
        onBackup={handleBackup}
        onRestore={handleRestore}
        lastBackupDate={lastBackupDate}
      />
    </AppProvider>
  );
};

interface AppContentProps {
  onLogout: () => void;
  bgColor: string;
  onBgColorChange: (color: string) => void;
  onBackup: () => void;
  onRestore: (file: File) => void;
  lastBackupDate: string | null;
}

const AppContent: React.FC<AppContentProps> = ({ onLogout, bgColor, onBgColorChange, onBackup, onRestore, lastBackupDate }) => {
  const [activeTab, setActiveTab] = useState('dashboard');
