import React, { useState, useMemo } from 'react';
import { useApp } from '../context/AppContext';
import { Calculator, AlertTriangle, HelpCircle, X } from 'lucide-react';
import { Product } from '../types';

const Pricing: React.FC = () => {
  const { 
    cfi, 
    platformConfig, 
    calculateFixedCostPercent,
    updateProduct,
    getSortedProducts,
    getProductCMV
  } = useApp();
  const [showHelp, setShowHelp] = useState(false);

  const fixedCostPct = calculateFixedCostPercent();
  const avgCardRate = (cfi.debitTax + cfi.creditTax) / 2;
  const variableCostsPct = avgCardRate + cfi.tax + cfi.royalties + cfi.marketing + cfi.voucherTax;
  const totalCfiCost = fixedCostPct + variableCostsPct;

  const sortedProducts = useMemo(() => getSortedProducts(), [getSortedProducts]);

  const calculateStorePrice = (cmv: number, profitMargin: number) => {
    const totalDeductions = (totalCfiCost + profitMargin) / 100;
    if (totalDeductions >= 1) return 0; 
    return cmv / (1 - totalDeductions);
  };

  const calculateMarketplacePrice = (pvLoja: number, feesPct: number, delivery: number, ci: number, coupon: number) => {
      const denominator = 1 - (feesPct / 100);
      if (denominator <= 0) return 0;
      return (pvLoja + delivery + ci + coupon) / denominator;
  };

  const handleUpdate = (productId: string, section: 'pricing', key: string, value: number) => {
      const product = sortedProducts.find(p => p.id === productId);
      if (!product) return;
      const newPricing = { ...product.pricing };
      if (key.includes('.')) {
          const [parent, child] = key.split('.');
          // @ts-ignore
          newPricing[parent] = { ...newPricing[parent], [child]: value };
      } else {
          // @ts-ignore
          newPricing[key] = value;
      }
      updateProduct(productId, { pricing: newPricing });
  };

  return (
    <div className="space-y-6 pb-20">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
          <div className="flex items-center gap-2">
            <h2 className="text-3xl font-bold text-gray-900 dark:text-white mb-2 uppercase">Preço de Venda</h2>
            <button onClick={() => setShowHelp(!showHelp)} className="text-gray-400 hover:text-brand-red transition-colors"><HelpCircle size={20} /></button>
          </div>
          <p className="text-gray-500 dark:text-gray-400">Sugestão de preços baseada na sua estrutura de custos e metas de lucro.</p>
        </div>
        <div className="bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 p-4 rounded-xl text-sm flex gap-6 shadow-lg">
            <div>
                <span className="block text-[10px] text-gray-500 uppercase font-bold">CFI Total (Fixo+Var)</span>
                <span className="text-xl font-bold text-brand-red">{totalCfiCost.toFixed(2)}%</span>
            </div>
        </div>
      </div>

      {showHelp && (
        <div className="bg-blue-50 dark:bg-gray-800/90 border border-blue-200 dark:border-blue-500/30 p-4 rounded-xl relative shadow-sm">
            <button onClick={() => setShowHelp(false)} className="absolute top-2 right-2 text-blue-400 hover:text-blue-300"><X size={16}/></button>
            <h4 className="font-bold text-blue-700 dark:text-blue-300 mb-2">Como usar esta tela?</h4>
            <p className="text-sm text-blue-800 dark:text-blue-200 leading-relaxed">
                Acompanhe o cálculo do Markup por Denominador para garantir o lucro em todos os canais.
            </p>
        </div>
      )}

      <div className="bg-white dark:bg-gray-800/90 border border-gray-200 dark:border-gray-700 rounded-xl overflow-hidden shadow-xl">
        <div className="overflow-x-auto overflow-y-visible pb-2" style={{ scrollbarGutter: 'stable' }}>
            <table className="w-full text-left border-collapse min-w-[2400px]" style={{ tableLayout: 'fixed' }}>
            <thead>
                <tr className="bg-gray-50 dark:bg-gray-800 text-gray-500 dark:text-gray-400 text-[10px] uppercase font-bold tracking-wider">
                    <th className="p-3 border-b border-gray-200 dark:border-gray-700 sticky left-0 z-30 bg-gray-50 dark:bg-gray-800 w-56 text-left shadow-sm">Produto</th>
                    <th className="p-3 border-b border-gray-200 dark:border-gray-700 text-center w-24">CMV + Emb</th>
                    <th className="p-3 border-b border-gray-200 dark:border-gray-700 text-center w-20">CFI %</th>
                    <th className="p-3 border-b border-gray-200 dark:border-gray-700 text-center w-24">Lucro %</th>
                    <th className="p-3 border-b border-gray-200 dark:border-gray-700 text-center w-32 bg-gray-200 dark:bg-gray-700 text-gray-900 dark:text-white border-x border-gray-300 dark:border-gray-600">PV Loja</th>
                    <th className="p-3 border-b border-red-100 dark:border-gray-700 bg-red-50 dark:bg-red-900/10 text-center w-20 text-red-900 dark:text-red-100">Ifood %</th>
                    <th className="p-3 border-b border-red-100 dark:border-gray-700 bg-red-50 dark:bg-red-900/10 text-center w-32 bg-brand-red text-white font-bold">PV Ifood</th>
                    <th className="p-3 border-b border-purple-100 dark:border-gray-700 bg-purple-50 dark:bg-purple-900/10 text-center w-32 bg-purple-600 text-white font-bold">PV CI</th>
                    <th className="p-3 border-b border-yellow-100 dark:border-gray-700 bg-yellow-50 dark:bg-yellow-900/10 text-center w-32 bg-yellow-600 text-white font-bold">PV 99Food</th>
                    <th className="p-3 border-b border-orange-100 dark:border-gray-700 bg-orange-50 dark:bg-orange-900/10 text-center w-32 bg-orange-600 text-white font-bold">PV Keeta</th>
                </tr>
            </thead>
            <tbody className="divide-y divide-gray-100 dark:divide-gray-700 text-xs">
                {sortedProducts.map(product => {
                    const cmv = getProductCMV(product);
                    const pricing = product.pricing || {};
                    const profitMargin = pricing.profitMargin !== undefined ? pricing.profitMargin : 20; 
                    const storePrice = calculateStorePrice(cmv, profitMargin);

                    const ifoodFee = pricing.ifood?.fee ?? platformConfig.ifood.fee;
                    const ifoodOnline = pricing.ifood?.onlinePayment ?? platformConfig.ifood.onlinePayment;
                    const ifoodAntic = pricing.ifood?.anticipation ?? platformConfig.ifood.anticipation;
                    const ifoodDel = pricing.ifood?.delivery ?? platformConfig.ifood.delivery;
                    const ifoodCoupon = pricing.ifood?.coupon ?? 0;
                    const ifoodPrice = calculateMarketplacePrice(storePrice, ifoodFee + ifoodOnline + ifoodAntic, ifoodDel, 0, ifoodCoupon);

                    const ciVal = pricing.ifood?.ciValue ?? platformConfig.ifood.ciValue;
                    const ifoodCIPrice = calculateMarketplacePrice(storePrice, ifoodFee + ifoodOnline + ifoodAntic, ifoodDel, ciVal, ifoodCoupon);

                    const food99Fee = pricing.food99?.fee ?? platformConfig.food99.fee;
                    const food99Price = calculateMarketplacePrice(storePrice, food99Fee + platformConfig.food99.onlinePayment, platformConfig.food99.delivery, 0, pricing.food99?.coupon ?? 0);

                    const keetaFee = pricing.keeta?.fee ?? platformConfig.keeta.fee;
                    const keetaPrice = calculateMarketplacePrice(storePrice, keetaFee + platformConfig.keeta.onlinePayment, platformConfig.keeta.delivery, 0, pricing.keeta?.coupon ?? 0);

                    return (
                        <tr key={product.id} className="hover:bg-gray-50 dark:hover:bg-gray-800 transition group">
                            <td className="p-3 font-bold text-gray-900 dark:text-white sticky left-0 z-20 bg-white dark:bg-gray-800 border-r border-gray-200 dark:border-gray-700 group-hover:bg-gray-50 dark:group-hover:bg-gray-700 transition-colors">
                                {product.name}
                            </td>
                            <td className="p-3 text-gray-500 dark:text-gray-400 text-center font-mono bg-gray-50 dark:bg-gray-800/50">R$ {cmv.toFixed(2)}</td>
                            <td className="p-3 text-center text-gray-600 dark:text-gray-400 bg-gray-50 dark:bg-gray-800/50">{totalCfiCost.toFixed(2)}%</td>
                            <td className="p-3 text-center bg-gray-50 dark:bg-gray-800/50">
                                <input type="number" step="0.1" className="bg-white dark:bg-gray-700 border border-gray-300 dark:border-gray-600 text-gray-900 dark:text-white w-12 text-center rounded focus:ring-1 focus:ring-brand-red outline-none" value={profitMargin} onChange={(e) => handleUpdate(product.id, 'pricing', 'profitMargin', parseFloat(e.target.value))} />
                            </td>
                            <td className="p-3 text-center font-bold text-lg text-gray-900 dark:text-white bg-gray-200 dark:bg-gray-700 border-x border-gray-300 dark:border-gray-600">R$ {storePrice.toFixed(2)}</td>
                            <td className="p-3 text-center bg-red-50 dark:bg-red-900/5"><input type="number" step="0.1" className="w-10 bg-transparent text-center outline-none" value={ifoodFee} onChange={e => handleUpdate(product.id, 'pricing', 'ifood.fee', parseFloat(e.target.value))} /></td>
                            <td className="p-3 text-center font-bold text-lg text-white bg-brand-red">R$ {ifoodPrice.toFixed(2)}</td>
                            <td className="p-3 text-center font-bold text-lg text-white bg-purple-600">R$ {ifoodCIPrice.toFixed(2)}</td>
                            <td className="p-3 text-center font-bold text-lg text-white bg-yellow-600">R$ {food99Price.toFixed(2)}</td>
                            <td className="p-3 text-center font-bold text-lg text-white bg-orange-600">R$ {keetaPrice.toFixed(2)}</td>
                        </tr>
                    );
                })}
            </tbody>
            </table>
        </div>
      </div>
    </div>
  );
};

