const Expenses: React.FC = () => {
  const { expenses, monthlyRevenue, categories, addExpenseWithInstallments, updateExpense, fixedCostMode, setFixedCostMode } = useApp();
  const [showHelp, setShowHelp] = useState(false);
  const now = new Date();
  const currentYear = now.getFullYear();
  const currentMonthIdx = now.getMonth();
  const [viewYear, setViewYear] = useState(currentYear);
  const [viewMonth, setViewMonth] = useState(MONTHS[currentMonthIdx].value);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingExpenseId, setEditingExpenseId] = useState<string | null>(null);
  const [formMonthStr, setFormMonthStr] = useState(`${currentYear}-${MONTHS[currentMonthIdx].value}`);
  const [desc, setDesc] = useState('');
  const [val, setVal] = useState('');
  const [cat, setCat] = useState('');
  const [dueDate, setDueDate] = useState('');
  const [isPaid, setIsPaid] = useState(false);
  const [installments, setInstallments] = useState(1);
  const selectedMonthKey = `${viewYear}-${viewMonth}`;
  const currentExpenses = useMemo(() => expenses.filter(e => e.month === selectedMonthKey), [expenses, selectedMonthKey]);

  const handleYearChange = (delta: number) => setViewYear(prev => prev + delta);
  const openNewExpenseModal = () => { setEditingExpenseId(null); setFormMonthStr(selectedMonthKey); setDesc(''); setVal(''); setCat(categories[0]?.name || ''); setDueDate(''); setIsPaid(false); setInstallments(1); setIsModalOpen(true); };
  const openEditModal = (exp: Expense) => { setEditingExpenseId(exp.id); setFormMonthStr(exp.month); setDesc(exp.description); setVal(exp.value.toString()); setCat(exp.category); setDueDate(exp.dueDate || ''); setIsPaid(!!exp.paid); setInstallments(1); setIsModalOpen(true); };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!desc || !val || !cat) return;
    if (editingExpenseId) { updateExpense(editingExpenseId, { description: desc, value: parseFloat(val), category: cat, month: formMonthStr, dueDate: dueDate, paid: isPaid }); } 
    else { addExpenseWithInstallments({ month: formMonthStr, description: desc, value: parseFloat(val), category: cat, dueDate: dueDate, paid: isPaid }, installments); }
    setIsModalOpen(false);
  };

  return (
    <div className="space-y-6 relative pb-20">
       <div className="bg-white/50 dark:bg-gray-800/50 border-b border-gray-200 dark:border-gray-700 pb-6 mb-6 flex flex-col xl:flex-row justify-between items-start xl:items-center gap-6 backdrop-blur-sm rounded-xl p-4">
         <div className="w-full xl:w-auto">
            <div className="flex items-center gap-2"><h2 className="text-3xl font-bold text-gray-900 dark:text-white uppercase tracking-wide">Despesas Fixas</h2><button onClick={() => setShowHelp(!showHelp)} className="text-gray-400 hover:text-brand-red"><HelpCircle size={20} /></button></div>
         </div>
         <div className="flex flex-col sm:flex-row items-center gap-4 bg-white dark:bg-gray-800 p-3 rounded-xl border border-gray-200 dark:border-gray-700 shadow-sm">
            <div className="flex bg-gray-100 dark:bg-gray-700 rounded p-1">
                <button onClick={() => setFixedCostMode('AVERAGE')} className={`px-3 py-1.5 text-xs font-bold rounded ${fixedCostMode === 'AVERAGE' ? 'bg-brand-red text-white' : 'text-gray-500'}`}>MÉDIA (12M)</button>
                <button onClick={() => setFixedCostMode('CURRENT_MONTH')} className={`px-3 py-1.5 text-xs font-bold rounded ${fixedCostMode === 'CURRENT_MONTH' ? 'bg-brand-red text-white' : 'text-gray-500'}`}>MÊS ATUAL</button>
            </div>
         </div>
       </div>
       <div className="grid grid-cols-1 xl:grid-cols-2 gap-8">
         <div className="space-y-4">
            <div className="bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-xl overflow-hidden shadow-lg h-[600px] flex flex-col">
                <div className="bg-gray-50 dark:bg-gray-800 px-6 py-3 border-b border-gray-200 dark:border-gray-700 flex justify-between items-center"><h3 className="font-bold text-gray-900 dark:text-white uppercase text-sm">Lançamentos</h3><button onClick={openNewExpenseModal} className="bg-brand-red text-white px-4 py-2 rounded-lg text-xs font-bold">+ NOVO</button></div>
                <div className="overflow-y-auto flex-1">
                    <table className="w-full text-left">
                        <tbody className="divide-y divide-gray-100 dark:divide-gray-700">
                            {currentExpenses.map(exp => (
                                <tr key={exp.id} className="hover:bg-gray-50 dark:hover:bg-gray-700/50 cursor-pointer" onClick={() => openEditModal(exp)}>
                                    <td className="px-4 py-3 text-sm font-medium dark:text-white uppercase">{exp.description}</td>
                                    <td className="px-4 py-3 text-sm text-right font-mono dark:text-gray-200">R$ {exp.value.toFixed(2)}</td>
                                </tr>
