import React, { useState } from 'react';
import { useApp } from '../context/AppContext';
import { Plus, Trash, Edit2, ShoppingBag, X, AlertTriangle, HelpCircle } from 'lucide-react';
import { Combo, ComboItem } from '../types';

const Combos: React.FC = () => {
  const { combos, products, getProductCMV, calculateTotalCfiPercent, platformConfig, addCombo, updateCombo, deleteCombo } = useApp();
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [showHelp, setShowHelp] = useState(false);
  const [name, setName] = useState('');
  const [profitMargin, setProfitMargin] = useState(15); 
  const [items, setItems] = useState<ComboItem[]>([]);
  const [ifoodFee, setIfoodFee] = useState(0);
  const [delivery, setDelivery] = useState(0);
  const [coupon, setCoupon] = useState(0);
  const totalCfiPercent = calculateTotalCfiPercent();
  const ifoodTotalFeeDefault = platformConfig.ifood.fee + platformConfig.ifood.onlinePayment + platformConfig.ifood.anticipation;

  const handleOpenModal = (combo?: Combo) => {
    if (combo) { setEditingId(combo.id); setName(combo.name); setProfitMargin(combo.profitMargin); setItems(combo.items); setIfoodFee(combo.ifoodFee); setDelivery(combo.delivery); setCoupon(combo.coupon); } 
    else { setEditingId(null); setName(''); setProfitMargin(15); setItems([]); setIfoodFee(ifoodTotalFeeDefault); setDelivery(platformConfig.ifood.delivery); setCoupon(0); }
    setIsModalOpen(true);
  };

  const calculateCombo = () => {
    let cmvCombo = 0;
    items.forEach(item => { const prod = products.find(p => p.id === item.productId); if (prod) cmvCombo += getProductCMV(prod) * item.quantity; });
    const totalDeductions = (totalCfiPercent + profitMargin) / 100;
    const pvLoja = totalDeductions < 1 ? cmvCombo / (1 - totalDeductions) : 0;
    const denominator = 1 - (ifoodFee / 100);
    const pvIfood = denominator > 0 ? (pvLoja + delivery + coupon) / denominator : 0;
    return { cmvCombo, pvLoja, pvIfood };
  };

  const { cmvCombo, pvLoja, pvIfood } = calculateCombo();

  return (
    <div className="space-y-6 pb-20">
      <div className="flex justify-between items-center">
        <div><h2 className="text-3xl font-bold text-gray-900 dark:text-white uppercase">Combos</h2></div>
        <button onClick={() => handleOpenModal()} className="bg-brand-red text-white px-4 py-3 rounded-lg font-bold shadow-lg">+ NOVO COMBO</button>
      </div>

      <div className="bg-white dark:bg-gray-800/90 border border-gray-200 dark:border-gray-700 rounded-xl overflow-hidden shadow-xl">
        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead className="bg-gray-50 dark:bg-gray-800 text-gray-500 dark:text-gray-400 text-[10px] uppercase font-bold">
               <tr><th>Nome</th><th>Itens</th><th className="text-right">CMV</th><th className="text-right">PV Loja</th><th className="text-right">PV iFood</th><th className="text-center">Ações</th></tr>
            </thead>
            <tbody className="divide-y divide-gray-100 dark:divide-gray-700 text-sm">
               {combos.map(combo => (
                   <tr key={combo.id} className="hover:bg-gray-50 dark:hover:bg-gray-700/50"><td className="px-6 py-4 font-bold dark:text-white">{combo.name}</td><td className="px-6 py-4 text-center dark:text-gray-300">{combo.items.length}</td><td className="px-6 py-4 text-right font-mono dark:text-gray-300">R$ {cmvCombo.toFixed(2)}</td><td className="px-6 py-4 text-right font-mono font-bold dark:text-white">R$ {pvLoja.toFixed(2)}</td><td className="px-6 py-4 text-right font-mono font-bold text-red-500">R$ {pvIfood.toFixed(2)}</td><td className="px-6 py-4 flex justify-center gap-3"><button onClick={() => handleOpenModal(combo)} className="text-blue-500"><Edit2 size={16}/></button></td></tr>
               ))}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

