              <input 
                type="text" 
                placeholder="Nova Categoria..." 
                value={newCatName}
                onChange={e => setNewCatName(e.target.value)}
                className="flex-1 bg-white dark:bg-black/40 border border-gray-300 dark:border-white/10 text-gray-900 dark:text-white rounded-lg p-2 focus:ring-1 focus:ring-brand-red outline-none text-sm"
              />
              <button type="submit" className="bg-brand-red hover:bg-red-700 text-white px-3 py-2 rounded-lg transition">
                <Plus size={18} />
              </button>
            </form>
          </div>

          <div className="flex-1 overflow-y-auto p-2 space-y-1">
            {categories.map((cat) => (
              <div key={cat.id} className="group flex items-center justify-between p-3 rounded-lg hover:bg-gray-50 dark:hover:bg-white/5 transition border border-transparent hover:border-gray-200 dark:hover:border-white/10">
                <span className="text-gray-700 dark:text-gray-300 text-sm">{cat.name}</span>
                <button 
                  onClick={() => deleteCategory(cat.id)}
                  className="text-gray-400 hover:text-red-500 opacity-0 group-hover:opacity-100 transition"
                >
                  <Trash2 size={16} />
                </button>
              </div>
            ))}
          </div>
        </div>

        {/* Suppliers Section */}
        <div className="glass-card border border-gray-200 dark:border-white/10 rounded-xl overflow-hidden flex flex-col h-[70vh] shadow-lg">
          <div className="bg-gray-50 dark:bg-white/5 p-4 border-b border-gray-200 dark:border-white/10 flex items-center justify-between">
             <div className="flex items-center gap-2 text-gray-900 dark:text-white font-bold uppercase text-sm">
               <Users className="text-blue-600 dark:text-blue-400" size={20} />
               Fornecedores
             </div>
          </div>

          <div className="p-4 border-b border-gray-200 dark:border-white/10 bg-gray-50/50 dark:bg-white/5">
            <form onSubmit={handleAddSupplier} className="space-y-2">
              <input 
                type="text" 
                placeholder="Nome..." 
                value={newSupName}
                onChange={e => setNewSupName(e.target.value)}
                className="w-full bg-white dark:bg-black/40 border border-gray-300 dark:border-white/10 text-gray-900 dark:text-white rounded-lg p-2 outline-none text-sm"
              />
              <div className="flex gap-2">
                <input 
                  type="text" 
                  placeholder="Contato..." 
                  value={newSupContact}
                  onChange={e => setNewSupContact(e.target.value)}
                  className="flex-1 bg-white dark:bg-black/40 border border-gray-300 dark:border-white/10 text-gray-900 dark:text-white rounded-lg p-2 outline-none text-sm"
                />
                <button type="submit" className="bg-brand-red text-white px-4 py-2 rounded-lg font-bold text-xs uppercase">Adicionar</button>
              </div>
            </form>
          </div>

          <div className="flex-1 overflow-y-auto p-2 space-y-1">
            {suppliers.map((sup) => (
