import React, { useState, useMemo } from 'react';
import { useApp } from '../context/AppContext';
import { ChevronLeft, ChevronRight, DollarSign, TrendingUp, AlertCircle, HelpCircle, X } from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell } from 'recharts';

const MONTHS = [
  { value: '01', label: 'Janeiro' }, { value: '02', label: 'Fevereiro' }, { value: '03', label: 'Março' }, { value: '04', label: 'Abril' }, { value: '05', label: 'Maio' }, { value: '06', label: 'Junho' }, { value: '07', label: 'Julho' }, { value: '08', label: 'Agosto' }, { value: '09', label: 'Setembro' }, { value: '10', label: 'Outubro' }, { value: '11', label: 'Novembro' }, { value: '12', label: 'Dezembro' },
];

const Billing: React.FC = () => {
  const { monthlyRevenue, updateMonthlyRevenue } = useApp();
  const [viewYear, setViewYear] = useState(new Date().getFullYear());
  const [showHelp, setShowHelp] = useState(false);

  const handleYearChange = (delta: number) => setViewYear(prev => prev + delta);

  const updateRevenueValue = (monthKey: string, valueStr: string) => {
    const value = parseFloat(valueStr) || 0;
    const exists = monthlyRevenue.find(r => r.month === monthKey);
    let newData = exists ? monthlyRevenue.map(r => r.month === monthKey ? { ...r, revenue: value } : r) : [...monthlyRevenue, { month: monthKey, revenue: value }];
    updateMonthlyRevenue(newData);
  };

  const yearData = useMemo(() => MONTHS.map(m => {
    const monthKey = `${viewYear}-${m.value}`;
    const entry = monthlyRevenue.find(r => r.month === monthKey);
    return { label: m.label, key: monthKey, value: entry ? entry.revenue : 0 };
  }), [viewYear, monthlyRevenue]);

  const averageRevenue = useMemo(() => {
    const activeMonths = monthlyRevenue.filter(r => r.revenue > 0).sort((a, b) => a.month.localeCompare(b.month)).slice(-12);
    return activeMonths.length === 0 ? 0 : activeMonths.reduce((acc, curr) => acc + curr.revenue, 0) / activeMonths.length;
  }, [monthlyRevenue]);

  const chartData = yearData.map(d => ({ name: d.label.substring(0, 3), fullLabel: d.label, revenue: d.value }));

  return (
    <div className="space-y-6 pb-20 relative z-10">
      <div className="glass-card border border-gray-200 dark:border-white/10 pb-6 flex flex-col xl:flex-row justify-between items-start xl:items-center gap-6 backdrop-blur-sm rounded-xl p-6">
         <div className="w-full xl:w-auto">
            <div className="flex items-center gap-2"><h2 className="text-3xl font-bold text-gray-900 dark:text-white uppercase tracking-wide">Faturamento</h2><button onClick={() => setShowHelp(!showHelp)} className="text-gray-400 hover:text-brand-red"><HelpCircle size={20} /></button></div>
         </div>
         <div className="flex items-center gap-4 bg-white/50 dark:bg-black/20 p-2 rounded-xl border border-gray-200 dark:border-white/10">
             <button onClick={() => handleYearChange(-1)} className="p-2 hover:bg-gray-100 dark:hover:bg-white/5 rounded-lg transition"><ChevronLeft size={20}/></button>
             <div className="text-center px-4 font-bold text-gray-900 dark:text-white">{viewYear}</div>
             <button onClick={() => handleYearChange(1)} className="p-2 hover:bg-gray-100 dark:hover:bg-white/5 rounded-lg transition"><ChevronRight size={20}/></button>
         </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-1 glass-card border border-gray-200 dark:border-white/10 rounded-xl overflow-hidden shadow-lg flex flex-col h-full">
            <div className="bg-gray-50/80 dark:bg-white/5 px-6 py-4 border-b border-gray-200 dark:border-white/10 flex items-center gap-2 uppercase text-xs font-bold dark:text-white"><DollarSign size={16} /> Entradas</div>
            <div className="flex-1 overflow-auto">
                <table className="w-full">
                    <tbody className="divide-y divide-gray-100 dark:divide-white/5">
                        {yearData.map((month) => (
                            <tr key={month.key} className="hover:bg-gray-50 dark:hover:bg-white/5 transition">
                                <td className="px-6 py-3 text-sm font-medium dark:text-gray-300">{month.label}</td>
                                <td className="px-6 py-3"><input type="number" step="0.01" value={month.value || ''} placeholder="0,00" onChange={(e) => updateRevenueValue(month.key, e.target.value)} className="w-full bg-gray-50 dark:bg-black/40 border border-gray-200 dark:border-white/10 text-gray-900 dark:text-white text-right rounded-lg py-2 px-3 text-sm font-mono outline-none" /></td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>
        </div>
        <div className="lg:col-span-2 space-y-6">
            <div className="glass-card border border-gray-200 dark:border-white/10 rounded-xl p-8 flex items-center justify-between shadow-xl">
                <div>
                    <p className="text-gray-500 dark:text-gray-400 text-xs uppercase font-bold tracking-widest">Média Mensal</p>
                    <h2 className="text-4xl font-black text-gray-900 dark:text-white mt-1">R$ {averageRevenue.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</h2>
                </div>
                <div className="bg-brand-red/10 p-4 rounded-2xl text-brand-red"><TrendingUp size={40} /></div>
            </div>
            <div className="glass-card border border-gray-200 dark:border-white/10 rounded-xl p-6 h-96 shadow-sm">
                <ResponsiveContainer width="100%" height="100%">
                    <BarChart data={chartData}>
                        <CartesianGrid strokeDasharray="3 3" vertical={false} opacity={0.1} />
                        <XAxis dataKey="name" stroke="#9CA3AF" tick={{fontSize: 10}} axisLine={false} tickLine={false} />
                        <YAxis stroke="#9CA3AF" tick={{fontSize: 10}} axisLine={false} tickLine={false} tickFormatter={(val) => `R$${val/1000}k`} />
                        <Tooltip contentStyle={{ backgroundColor: 'rgba(0,0,0,0.8)', border: 'none', borderRadius: '8px', color: '#FFF' }} />
                        <Bar dataKey="revenue" radius={[4, 4, 0, 0]}>
                            {chartData.map((entry, index) => <Cell key={`cell-${index}`} fill={entry.revenue > 0 ? '#D90429' : 'rgba(156,163,175,0.2)'} />)}
                        </Bar>
                    </BarChart>
                </ResponsiveContainer>
            </div>
        </div>
      </div>
    </div>
  );
};

