import React, { useState, useRef } from 'react';
import { Plus, Store, ArrowRight, MapPin, Edit2, Upload, X, Copy, CheckCircle, Trash2, AlertTriangle, Tags, TrendingUp } from 'lucide-react';
import { StoreInfo } from '../types';

interface StoreListProps {
  stores: StoreInfo[];
  onSelectStore: (storeId: string) => void;
  onAddStore: (store: StoreInfo) => void;
  onUpdateStore: (store: StoreInfo) => void;
  onDeleteStore?: (storeId: string) => void;
  onReplicate?: (sourceId: string, targetId: string, type: string) => void;
}

const REPLICATION_OPTIONS = [
    { value: 'all', label: 'Tudo (Clonar Loja)' },
    { value: 'ingredients', label: 'Aba Insumos' },
    { value: 'products', label: 'Aba Cardápio & Fichas' },
    { value: 'combos', label: 'Aba Combos' },
    { value: 'cfi', label: 'Aba CFI & Taxas' },
    { value: 'platform', label: 'Config. Marketplaces' },
    { value: 'expenses', label: 'Aba Despesas Fixas' },
    { value: 'categories', label: 'Categorias & Fornecedores' },
];

const StoreList: React.FC<StoreListProps> = ({ stores, onSelectStore, onAddStore, onUpdateStore, onDeleteStore, onReplicate }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingStore, setEditingStore] = useState<StoreInfo | null>(null);
  const [isReplicateOpen, setIsReplicateOpen] = useState(false);
  const [sourceId, setSourceId] = useState('');
  const [targetId, setTargetId] = useState('');
  const [replicationType, setReplicationType] = useState('products');
  const [showSuccess, setShowSuccess] = useState(false);
  const [storeToDelete, setStoreToDelete] = useState<StoreInfo | null>(null);
  const [name, setName] = useState('');
  const [address, setAddress] = useState('');
  const [logo, setLogo] = useState('');

  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleOpenModal = (store?: StoreInfo) => {
    if (store) {
      setEditingStore(store);
      setName(store.name);
      setAddress(store.address || '');
      setLogo(store.logo || '');
    } else {
      setEditingStore(null);
      setName('');
      setAddress('');
      setLogo('');
    }
    setIsModalOpen(true);
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setLogo(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!name) return;
    onUpdateStore({ id: editingStore?.id, name, address, logo });
    setIsModalOpen(false);
  };

  const confirmDelete = () => {
    if (storeToDelete && onDeleteStore && storeToDelete.id) {
        onDeleteStore(storeToDelete.id);
        setStoreToDelete(null);
    }
  };

  const handleReplicateSubmit = (e: React.FormEvent) => {
      e.preventDefault();
      if (!sourceId || !targetId || !onReplicate) return;
      onReplicate(sourceId, targetId, replicationType);
      setShowSuccess(true);
      setTimeout(() => { setIsReplicateOpen(false); setShowSuccess(false); }, 1500);
  };

  return (
    <div className="flex flex-col items-center justify-center p-8 relative overflow-hidden min-h-screen">
      <div className="max-w-6xl w-full space-y-10 relative z-10 text-center">

        <div className="flex flex-col items-center justify-center space-y-6 mb-16">
            <div className="relative w-20 h-20 glass-card rounded-2xl flex items-center justify-center shadow-2xl">
                <Tags size={40} className="text-yellow-500" />
            </div>
            <div className="space-y-2">
                 <h1 className="text-4xl md:text-5xl font-black text-gray-900 dark:text-white tracking-tight uppercase">
                    Lucro Fácil
                 </h1>
                 <p className="text-gray-500 dark:text-gray-400 font-medium">
                    Gestão e Precificação Inteligente
                 </p>
            </div>
            {onReplicate && (
                <button onClick={() => setIsReplicateOpen(true)} className="glass-card px-4 py-2 rounded-xl text-xs font-bold flex items-center gap-2 hover:border-brand-red transition">
                    <Copy size={14} /> REPLICAR DADOS
                </button>
            )}
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
            {stores.map(store => (
                <div 
                    key={store.id}
                    className="glass-card p-6 rounded-2xl text-left hover:border-brand-red transition-all duration-300 relative group flex flex-col h-full cursor-pointer"
                    onClick={() => onSelectStore(store.id!)}
                >
                    <div className="absolute top-3 right-3 flex gap-2 opacity-0 group-hover:opacity-100 transition">
                        <button onClick={(e) => { e.stopPropagation(); handleOpenModal(store); }} className="p-1.5 rounded-full bg-white/10 text-gray-400 hover:text-white"><Edit2 size={12}/></button>
                        <button onClick={(e) => { e.stopPropagation(); setStoreToDelete(store); }} className="p-1.5 rounded-full bg-white/10 text-gray-400 hover:text-red-500"><Trash2 size={12}/></button>
                    </div>

                    <div className="flex-1">
                        <div className="w-12 h-12 glass-card rounded-xl flex items-center justify-center mb-4 overflow-hidden">
                            {store.logo ? <img src={store.logo} className="w-full h-full object-cover" /> : <Store size={20}/>}
                        </div>
                        <h3 className="text-lg font-bold text-gray-900 dark:text-white mb-1 truncate">{store.name}</h3>
                        <div className="flex items-center gap-1.5 text-[10px] text-gray-500 uppercase font-bold truncate">
                            <MapPin size={10} /> {store.address || 'Sem endereço'}
                        </div>
                    </div>

                    <div className="pt-4 border-t border-gray-100 dark:border-white/5 mt-4 flex items-center justify-between text-[10px] font-black text-gray-400 group-hover:text-brand-red uppercase tracking-widest">
                        <span>Acessar</span>
                        <ArrowRight size={12} />
                    </div>
                </div>
            ))}

            <button onClick={() => handleOpenModal()} className="border-2 border-dashed border-gray-300 dark:border-white/10 rounded-2xl flex flex-col items-center justify-center gap-4 text-gray-400 hover:text-white hover:border-brand-red transition min-h-[180px]">
                <Plus size={32} />
                <span className="text-[10px] font-black uppercase tracking-widest">Nova Loja</span>
            </button>
        </div>
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 bg-black/90 backdrop-blur-sm flex items-center justify-center z-50 p-4">
            <div className="bg-white dark:bg-gray-900 border border-gray-200 dark:border-white/10 rounded-2xl w-full max-w-sm overflow-hidden shadow-2xl">
                <div className="p-4 border-b border-gray-100 dark:border-white/5 flex justify-between items-center">
                    <h3 className="font-bold text-gray-900 dark:text-white uppercase text-xs tracking-widest">Configurar Unidade</h3>
                    <button onClick={() => setIsModalOpen(false)}><X size={20}/></button>
                </div>
                <form onSubmit={handleSubmit} className="p-6 space-y-4">
                    <input type="text" value={name} onChange={e => setName(e.target.value)} required className="w-full bg-gray-50 dark:bg-white/5 border border-gray-200 dark:border-white/10 rounded-lg p-3 text-sm outline-none focus:ring-1 focus:ring-brand-red" placeholder="Nome da Loja" />
                    <input type="text" value={address} onChange={e => setAddress(e.target.value)} className="w-full bg-gray-50 dark:bg-white/5 border border-gray-200 dark:border-white/10 rounded-lg p-3 text-sm outline-none focus:ring-1 focus:ring-brand-red" placeholder="Endereço" />
                    <button type="submit" className="w-full py-3 bg-brand-red text-white font-black rounded-lg uppercase text-[10px] tracking-widest">Salvar Unidade</button>
                </form>
            </div>
        </div>
      )}
    </div>
  );
};

