                              <div className={`p-3 rounded-xl bg-white/5 ${step.color}`}><Icon size={20}/></div>
                              <h3 className="font-bold text-gray-900 dark:text-white uppercase text-xs tracking-widest">{step.title}</h3>
                          </div>
                          {isOpen ? <ChevronUp size={16} /> : <ChevronDown size={16} />}
                      </button>
                      {isOpen && (
                        <div className="px-8 pb-8 pt-4 border-t border-white/5 animate-none">
                            <div className="text-gray-300" dangerouslySetInnerHTML={{ __html: step.content }} />
                        </div>
                      )}
                  </div>
              );
          })}
          {filteredSteps.length === 0 && <p className="text-center py-20 text-gray-500 italic">Nenhum tópico encontrado para sua busca.</p>}
      </div>

      <footer className="max-w-4xl mx-auto p-8 glass-card rounded-2xl flex flex-col md:flex-row items-center justify-between gap-6 border-brand-red/20">
          <div className="flex items-center gap-4">
              <div className="bg-brand-red/10 p-3 rounded-full text-brand-red"><Zap size={24}/></div>
              <div className="text-left">
                  <h4 className="font-bold text-gray-900 dark:text-white uppercase text-xs">Suporte Direto</h4>
                  <p className="text-[10px] text-gray-500 uppercase font-bold">Dúvidas avançadas ou erros no sistema?</p>
              </div>
          </div>
          <a href="mailto:suporte@carreiroapps.com" className="bg-brand-red text-white px-6 py-3 rounded-xl font-black text-[10px] uppercase tracking-widest hover:scale-105 transition">Contatar Engenharia</a>
      </footer>
    </div>
  );
};

