                                          <th className="px-4 py-3 text-center w-10 no-print"></th>
                                      </tr>
                                  </thead>
                                  <tbody className="divide-y divide-gray-100 dark:divide-gray-800 text-sm">
                                      {shoppingList.length === 0 && (
                                          <tr><td colSpan={8} className="text-center py-20 text-gray-400 italic">Sua lista está vazia. Adicione itens para começar.</td></tr>
                                      )}
                                      {shoppingList.map((item, idx) => (
                                          <tr key={idx} className="hover:bg-gray-50 dark:hover:bg-gray-900/50">
                                              <td className="px-4 py-3 font-bold text-gray-800 dark:text-gray-200">{item.ingredient.name}</td>
                                              <td className="px-4 py-3 text-center font-bold">{item.packages}</td>
                                              <td className="px-4 py-3 text-center text-gray-500">{item.ingredient.packageQuantity}</td>
                                              <td className="px-4 py-3 text-center text-xs text-gray-500">{item.ingredient.unit === MeasureUnit.UN ? 'UN' : item.ingredient.unit === MeasureUnit.G ? 'GRAMAS' : 'ML'}</td>
                                              <td className="px-4 py-3 text-right font-mono text-gray-600 dark:text-gray-400">
                                                  {item.packages * item.ingredient.packageQuantity} 
                                                  <span className="text-[10px] ml-1 text-gray-400">{item.ingredient.unit === MeasureUnit.UN ? 'un' : item.ingredient.unit === MeasureUnit.G ? 'g' : 'ml'}</span>
                                              </td>
                                              <td className="px-4 py-3 text-right font-mono text-gray-500">R$ {item.ingredient.price.toFixed(2)}</td>
                                              <td className="px-4 py-3 text-right font-bold text-gray-900 dark:text-white font-mono">R$ {(item.packages * item.ingredient.price).toFixed(2)}</td>
                                              <td className="px-4 py-3 text-center no-print">
                                                  <button onClick={() => removeShoppingListItem(idx)} className="text-gray-400 hover:text-red-500"><Trash2 size={14} /></button>
                                              </td>
                                          </tr>
                                      ))}
                                  </tbody>
                                  <tfoot className="bg-gray-50 dark:bg-gray-900 border-t border-gray-200 dark:border-gray-800">
                                      <tr>
                                          <td colSpan={6} className="px-4 py-4 text-right font-bold uppercase text-xs text-gray-500">Total Geral</td>
                                          <td className="px-4 py-4 text-right font-black text-xl text-emerald-600 dark:text-emerald-400">R$ {grandTotal.toFixed(2)}</td>
                                          <td className="no-print"></td>
                                      </tr>
                                  </tfoot>
                              </table>
                          </div>
                      </div>
                  </div>

                  <div className="p-4 border-t border-gray-200 dark:border-gray-800 flex justify-between items-center bg-white dark:bg-gray-900 rounded-b-xl no-print">
                      <div className="text-xs text-gray-400 italic">
                          * Dados baseados no cadastro de insumos.
                      </div>
                      <div className="flex gap-2">
                          <button 
                            onClick={handlePrint} 
                            disabled={shoppingList.length === 0}
                            className="px-4 py-2 rounded-lg border border-gray-300 dark:border-gray-700 text-gray-700 dark:text-white font-bold hover:bg-gray-50 dark:hover:bg-gray-800 transition flex items-center gap-2 disabled:opacity-50"
                          >
                              <Printer size={16} /> Imprimir
                          </button>
                          <button 
                            onClick={handlePrint}
                            disabled={shoppingList.length === 0}
                            className="px-4 py-2 rounded-lg bg-emerald-600 text-white font-bold hover:bg-emerald-700 transition flex items-center gap-2 disabled:opacity-50"
                          >
                              <FileText size={16} /> Salvar PDF
                          </button>
                          <button 
                            onClick={() => setIsShoppingModalOpen(false)} 
                            className="px-6 py-2 rounded-lg bg-gray-200 dark:bg-gray-800 hover:bg-gray-300 dark:hover:bg-gray-700 text-gray-700 dark:text-white font-bold transition ml-2"
                          >
                              Fechar
                          </button>
                      </div>
                  </div>

              </div>
          </div>
      )}

      {/* Editor Modal (Existing) */}
      {isModalOpen && (
        <div className="fixed inset-0 bg-black/80 backdrop-blur-sm flex items-center justify-center z-50 p-4">
          <div className="bg-white dark:bg-gray-900 border border-gray-200 dark:border-gray-800 p-6 rounded-xl w-full max-w-lg shadow-2xl animate-fade-in">
            <h3 className="text-xl font-bold text-gray-900 dark:text-white mb-6 uppercase flex items-center gap-2">
                {editingId ? <Edit2 size={20} /> : <Plus size={20} />}
                {editingId ? 'Editar Insumo' : 'Novo Insumo'}
            </h3>
            <form onSubmit={handleSubmit} className="space-y-4">
              <div>
                <label className="block text-gray-500 dark:text-gray-400 text-xs font-bold uppercase mb-1">Nome do Insumo</label>
                <input 
                  type="text" 
                  required
                  value={formData.name}
                  onChange={e => setFormData({...formData, name: e.target.value})}
                  className="w-full bg-gray-50 dark:bg-gray-800 border border-gray-300 dark:border-gray-700 rounded-lg p-3 text-gray-900 dark:text-white focus:ring-2 focus:ring-brand-red outline-none"
                />
              </div>

              <div className="grid grid-cols-2 gap-4">
                 <div>
                    <label className="block text-gray-500 dark:text-gray-400 text-xs font-bold uppercase mb-1">Unidade de Medida</label>
                    <select 
                        value={formData.unit}
                        onChange={e => setFormData({...formData, unit: e.target.value as MeasureUnit})}
                        className="w-full bg-gray-50 dark:bg-gray-800 border border-gray-300 dark:border-gray-700 rounded-lg p-3 text-gray-900 dark:text-white focus:ring-2 focus:ring-brand-red outline-none"
                    >
                        <option value={MeasureUnit.UN}>Unidade</option>
                        <option value={MeasureUnit.G}>Gramas</option>
                        <option value={MeasureUnit.ML}>Mililitros</option>
                    </select>
                 </div>
                 <div>
                    <label className="block text-gray-500 dark:text-gray-400 text-xs font-bold uppercase mb-1">Preço do Pacote (R$)</label>
                    <input 
                        type="number" 
                        step="0.01"
                        required
                        value={formData.price}
                        onChange={e => setFormData({...formData, price: parseFloat(e.target.value)})}
                        className="w-full bg-gray-50 dark:bg-gray-800 border border-gray-300 dark:border-gray-700 rounded-lg p-3 text-gray-900 dark:text-white focus:ring-2 focus:ring-brand-red outline-none"
                    />
                 </div>
              </div>

              <div className="grid grid-cols-2 gap-4">
                 <div>
                    <label className="block text-gray-500 dark:text-gray-400 text-xs font-bold uppercase mb-1">Peso/Qtd no Pacote</label>
                    <input 
                        type="number" 
                        step="0.01"
                        required
                        value={formData.packageQuantity}
                        onChange={e => setFormData({...formData, packageQuantity: parseFloat(e.target.value)})}
                        className="w-full bg-gray-50 dark:bg-gray-800 border border-gray-300 dark:border-gray-700 rounded-lg p-3 text-gray-900 dark:text-white focus:ring-2 focus:ring-brand-red outline-none"
                    />
                 </div>
                 <div>
                    <label className="block text-gray-500 dark:text-gray-400 text-xs font-bold uppercase mb-1">Perda (%)</label>
                    <input 
                        type="number" 
                        step="0.1"
                        max="100"
                        min="0"
                        required
                        value={formData.lossPercent}
                        onChange={e => setFormData({...formData, lossPercent: parseFloat(e.target.value)})}
                        className="w-full bg-gray-50 dark:bg-gray-800 border border-gray-300 dark:border-gray-700 rounded-lg p-3 text-gray-900 dark:text-white focus:ring-2 focus:ring-brand-red outline-none"
                    />
                 </div>
              </div>

              {/* Live Preview of Calculation */}
              <div className="bg-gray-50 dark:bg-gray-800/50 p-4 rounded-lg border border-gray-200 dark:border-gray-700 mt-4">
                  <p className="text-xs text-gray-500 uppercase font-bold mb-2">Simulação de Custo Real</p>
                  <div className="flex justify-between items-center text-sm">
                      <span className="text-gray-500 dark:text-gray-400">Quantidade Real (com perda):</span>
                      <span className="text-gray-900 dark:text-white font-mono">
                          {((formData.packageQuantity || 0) * (1 - ((formData.lossPercent || 0)/100))).toFixed(2)} 
                          {' '}{formData.unit === MeasureUnit.G ? 'g' : formData.unit === MeasureUnit.ML ? 'ml' : 'un'}
                      </span>
                  </div>
                  <div className="flex justify-between items-center text-sm mt-1">
                      <span className="text-gray-500 dark:text-gray-400">Custo Final por Unidade:</span>
                      <span className="text-brand-red font-bold font-mono">
                         R$ {
                            formData.packageQuantity && formData.price 
                            ? (formData.price / ((formData.packageQuantity) * (1 - ((formData.lossPercent || 0)/100)))).toFixed(4)
                            : '0.0000'
                         }
                      </span>
                  </div>
              </div>

              <div className="flex justify-end gap-3 mt-6">
                <button type="button" onClick={() => setIsModalOpen(false)} className="px-6 py-3 text-gray-600 dark:text-gray-400 hover:text-gray-900 dark:hover:text-white font-bold bg-gray-200 dark:bg-gray-800 rounded-lg transition">Cancelar</button>
                <button type="submit" className="bg-brand-red text-white px-6 py-3 rounded-lg font-bold hover:bg-red-700 transition shadow-lg shadow-red-900/20">Salvar Insumo</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default Ingredients;

import { defineConfig } from 'vite'
import react from '@vitejs/plugin-react'

// https://vitejs.dev/config/
export default defineConfig({
  plugins: [react()],
  // Define a base como relativa ('./') para que os assets (js/css) 
  // sejam carregados corretamente independente do repositório/subpasta no GitHub Pages.
  base: './', 
  build: {
    outDir: 'dist',
    assetsDir: 'assets',
  }
})

import React, { createContext, useContext, useState, ReactNode, useEffect, useRef } from 'react';
import { GlobalState, Ingredient, Product, Expense, MonthlyData, CfiConfig, PlatformConfig, Category, Supplier, FixedCostMode, Combo, StoreInfo, MenuCategory } from '../types';
import { INITIAL_STATE, EMPTY_STATE } from '../constants';

interface AppContextType extends GlobalState {
  addIngredient: (ing: Ingredient) => void;
  updateIngredient: (id: string, ing: Partial<Ingredient>) => void;
  deleteIngredient: (id: string) => void;

  addProduct: (prod: Product) => void;
  updateProduct: (id: string, prod: Partial<Product>) => void;
  deleteProduct: (id: string) => void;
  reorderProduct: (id: string, direction: 'up' | 'down') => void;

  addMenuCategory: (name: string) => void;
  updateMenuCategory: (id: string, name: string) => void;
  deleteMenuCategory: (id: string) => void;
  reorderMenuCategory: (id: string, direction: 'up' | 'down') => void;

  addCombo: (combo: Combo) => void;
  updateCombo: (id: string, combo: Partial<Combo>) => void;
  deleteCombo: (id: string) => void;

  addExpense: (exp: Expense) => void;
  updateExpense: (id: string, exp: Partial<Expense>) => void;
  addExpenseWithInstallments: (baseExp: Omit<Expense, 'id' | 'installment'>, installments: number) => void;

  addCategory: (cat: Category) => void;
  deleteCategory: (id: string) => void;

  addSupplier: (sup: Supplier) => void;
  deleteSupplier: (id: string) => void;

  updateCfi: (cfi: Partial<CfiConfig>) => void;
  updatePlatformConfig: (cfg: Partial<PlatformConfig>) => void;
  updateMonthlyRevenue: (data: MonthlyData[]) => void;
  updateStoreInfo: (info: Partial<StoreInfo>) => void;

  setFixedCostMode: (mode: FixedCostMode) => void;

  getIngredientRealCost: (ing: Ingredient) => number;
  getProductCMV: (prod: Product) => number;
  calculateFixedCostPercent: (currentMonth?: string) => number;
  calculateTotalCfiPercent: () => number;
  getSortedProducts: () => Product[];
}

const AppContext = createContext<AppContextType | undefined>(undefined);

export const AppProvider: React.FC<{ 
  children: ReactNode; 
  storeId: string;
  initialData?: GlobalState;
  onStateChange?: (newState: GlobalState) => void;
}> = ({ children, storeId, initialData, onStateChange }) => {

  const [state, setState] = useState<GlobalState>(() => {
    if (initialData) {
        // DATA GUARD: Ensure all arrays are initialized even if missing in initialData (localStorage/Backup issues)
        return {
            ...EMPTY_STATE, // Base defaults
            ...initialData, // User data overwrites
            ingredients: initialData.ingredients || [],
            products: initialData.products || [],
            menuCategories: initialData.menuCategories || [],
            combos: initialData.combos || [],
            expenses: initialData.expenses || [],
            monthlyRevenue: initialData.monthlyRevenue || [],
            categories: initialData.categories || [],
            suppliers: initialData.suppliers || [],
            // Deep merge objects if necessary, but shallow merge for config objects usually suffices if they exist
            cfi: { ...EMPTY_STATE.cfi, ...(initialData.cfi || {}) },
            platformConfig: { 
                ifood: { ...EMPTY_STATE.platformConfig.ifood, ...(initialData.platformConfig?.ifood || {}) },
                food99: { ...EMPTY_STATE.platformConfig.food99, ...(initialData.platformConfig?.food99 || {}) },
                keeta: { ...EMPTY_STATE.platformConfig.keeta, ...(initialData.platformConfig?.keeta || {}) },
            }
        };
    }
    return storeId === '1' ? INITIAL_STATE : EMPTY_STATE;
  });

  const isFirstRender = useRef(true);
  useEffect(() => {
    if (isFirstRender.current) {
      isFirstRender.current = false;
      return;
    }
    if (onStateChange) onStateChange(state);
  }, [state, onStateChange]);

  // --- ACTIONS ---

  const addIngredient = (ing: Ingredient) => setState(s => ({ ...s, ingredients: [...s.ingredients, ing] }));
  const updateIngredient = (id: string, data: Partial<Ingredient>) => {
    setState(s => ({ ...s, ingredients: s.ingredients.map(i => i.id === id ? { ...i, ...data } : i) }));
  };
  const deleteIngredient = (id: string) => setState(s => ({ ...s, ingredients: s.ingredients.filter(i => i.id !== id) }));

  // Products
  const addProduct = (prod: Product) => setState(s => {
      const sameCat = s.products.filter(p => p.category === prod.category);
      const maxOrder = sameCat.length > 0 ? Math.max(...sameCat.map(p => p.order)) : -1;
      return { ...s, products: [...s.products, { ...prod, order: maxOrder + 1 }] };
  });

  const updateProduct = (id: string, data: Partial<Product>) => {
    setState(s => ({ ...s, products: s.products.map(p => p.id === id ? { ...p, ...data } : p) }));
  };

  const deleteProduct = (id: string) => setState(s => ({ ...s, products: s.products.filter(p => p.id !== id) }));

  const reorderProduct = (id: string, direction: 'up' | 'down') => {
    setState(s => {
      const product = s.products.find(p => p.id === id);
      if (!product) return s;

      const sameCat = s.products
        .filter(p => p.category === product.category)
        .sort((a, b) => a.order - b.order);

      const idx = sameCat.findIndex(p => p.id === id);
      if (direction === 'up' && idx === 0) return s;
      if (direction === 'down' && idx === sameCat.length - 1) return s;

      const targetIdx = direction === 'up' ? idx - 1 : idx + 1;
      const targetProduct = sameCat[targetIdx];

      const newProducts = s.products.map(p => {
        if (p.id === product.id) return { ...p, order: targetProduct.order };
        if (p.id === targetProduct.id) return { ...p, order: product.order };
        return p;
      });

      return { ...s, products: newProducts };
    });
  };

  // Menu Categories
  const addMenuCategory = (name: string) => setState(s => {
      const maxOrder = s.menuCategories.length > 0 ? Math.max(...s.menuCategories.map(c => c.order)) : -1;
      return { ...s, menuCategories: [...s.menuCategories, { id: Date.now().toString(), name, order: maxOrder + 1 }] };
  });

  const updateMenuCategory = (id: string, name: string) => setState(s => ({
    ...s,
    menuCategories: s.menuCategories.map(c => c.id === id ? { ...c, name } : c),
    products: s.products.map(p => {
      const oldCat = s.menuCategories.find(cat => cat.id === id);
      if (oldCat && p.category === oldCat.name) {
        return { ...p, category: name };
      }
      return p;
    })
  }));

  const deleteMenuCategory = (id: string) => setState(s => {
    const categoryToDelete = s.menuCategories.find(c => c.id === id);
    const catName = categoryToDelete?.name || "";

    return {
      ...s,
      menuCategories: s.menuCategories.filter(c => c.id !== id),
      // Move produtos que usavam essa categoria para "Sem Categoria"
      products: s.products.map(p => p.category === catName ? { ...p, category: "Sem Categoria" } : p)
    };
  });

  const reorderMenuCategory = (id: string, direction: 'up' | 'down') => {
    setState(s => {
        const sorted = [...s.menuCategories].sort((a,b) => a.order - b.order);
        const idx = sorted.findIndex(c => c.id === id);
        if (direction === 'up' && idx === 0) return s;
        if (direction === 'down' && idx === sorted.length - 1) return s;

        const targetIdx = direction === 'up' ? idx - 1 : idx + 1;
        const current = sorted[idx];
        const target = sorted[targetIdx];

        const newList = s.menuCategories.map(c => {
            if (c.id === current.id) return { ...c, order: target.order };
            if (c.id === target.id) return { ...c, order: current.order };
            return c;
        });
        return { ...s, menuCategories: newList };
    });
  };

  const addCombo = (combo: Combo) => setState(s => ({ ...s, combos: [...s.combos, combo] }));
  const updateCombo = (id: string, data: Partial<Combo>) => {
    setState(s => ({ ...s, combos: s.combos.map(c => c.id === id ? { ...c, ...data } : c) }));
  };
  const deleteCombo = (id: string) => setState(s => ({ ...s, combos: s.combos.filter(c => c.id !== id) }));

  const addExpense = (exp: Expense) => setState(s => ({ ...s, expenses: [...s.expenses, exp] }));
  const updateExpense = (id: string, data: Partial<Expense>) => {
    setState(s => ({ ...s, expenses: s.expenses.map(e => e.id === id ? { ...e, ...data } : e) }));
  };
  const addExpenseWithInstallments = (baseExp: Omit<Expense, 'id' | 'installment'>, installments: number) => {
    if (installments <= 1) {
      addExpense({ ...baseExp, id: Math.random().toString(36).substr(2, 9) });
      return;
    }
    const newExpenses: Expense[] = [];
    const groupId = Math.random().toString(36).substr(2, 9);
    let [year, month] = baseExp.month.split('-').map(Number);
    for (let i = 1; i <= installments; i++) {
      const monthStr = `${year}-${month.toString().padStart(2, '0')}`;
      let dueDateStr = undefined;
      if (baseExp.dueDate) {
        const [dYear, dMonth, dDay] = baseExp.dueDate.split('-').map(Number);
        let targetMonth = dMonth + (i - 1);
        let targetYear = dYear;
        while (targetMonth > 12) { targetMonth -= 12; targetYear++; }
        dueDateStr = `${targetYear}-${targetMonth.toString().padStart(2, '0')}-${dDay.toString().padStart(2, '0')}`;
      }
      newExpenses.push({ ...baseExp, id: Math.random().toString(36).substr(2, 9), month: monthStr, dueDate: dueDateStr, installment: { current: i, total: installments, id: groupId } });
      month++; if (month > 12) { month = 1; year++; }
    }
    setState(s => ({ ...s, expenses: [...s.expenses, ...newExpenses] }));
  };

  const addCategory = (cat: Category) => setState(s => ({ ...s, categories: [...s.categories, cat] }));
  const deleteCategory = (id: string) => setState(s => ({ ...s, categories: s.categories.filter(c => c.id !== id) }));
  const addSupplier = (sup: Supplier) => setState(s => ({ ...s, suppliers: [...s.suppliers, sup] }));
  const deleteSupplier = (id: string) => setState(s => ({ ...s, suppliers: s.suppliers.filter(s => s.id !== id) }));
  const updateCfi = (cfi: Partial<CfiConfig>) => setState(s => ({ ...s, cfi: { ...s.cfi, ...cfi } }));
  const updatePlatformConfig = (cfg: Partial<PlatformConfig>) => {
    setState(s => ({ ...s, platformConfig: { ...s.platformConfig, ...cfg, ifood: { ...s.platformConfig.ifood, ...(cfg.ifood || {}) }, food99: { ...s.platformConfig.food99, ...(cfg.food99 || {}) } } }));
  };
  const updateMonthlyRevenue = (data: MonthlyData[]) => setState(s => ({ ...s, monthlyRevenue: data }));
  const updateStoreInfo = (info: Partial<StoreInfo>) => setState(s => ({ ...s, storeInfo: { ...s.storeInfo, ...info } }));
  const setFixedCostMode = (mode: FixedCostMode) => setState(s => ({ ...s, fixedCostMode: mode }));

  // --- CALCULATIONS ---

  const getIngredientRealCost = (ing: Ingredient) => {
    if (!ing.packageQuantity || ing.packageQuantity <= 0) return 0;
    const realQty = ing.packageQuantity * (1 - (ing.lossPercent / 100));
    if (realQty <= 0) return 0;
    return ing.price / realQty;
  };

  const getProductCMV = (prod: Product) => {
    return (prod.ingredients || []).reduce((total, item) => {
      const ing = state.ingredients.find(i => i.id === item.ingredientId);
      if (!ing) return total;
      const realPrice = getIngredientRealCost(ing);
      return total + (realPrice * item.quantity);
    }, 0);
  };

  const calculateFixedCostPercent = (currentMonth?: string) => {
    // Ensure arrays are present before reducing
    const safeExpenses = state.expenses || [];
    const safeRevenue = state.monthlyRevenue || [];

    if (state.fixedCostMode === 'AVERAGE') {
       const expenseMonths = safeExpenses.map(e => e.month);
       const revenueMonths = safeRevenue.filter(r => r.revenue > 0).map(r => r.month);
       const allMonths = Array.from(new Set([...expenseMonths, ...revenueMonths])).sort();
       const last12 = allMonths.slice(-12);
       let totalCost = 0, totalRev = 0;
       last12.forEach(m => {
          const exp = safeExpenses.filter(e => e.month === m).reduce((s, e) => s + e.value, 0);
          const rev = safeRevenue.find(r => r.month === m)?.revenue || 0;
          if (exp > 0 || rev > 0) { totalCost += exp; if(rev > 0) totalRev += rev; }
       });
       if (totalRev === 0) return 0;
       return (totalCost / totalRev) * 100;
    } else {
        const targetMonth = currentMonth || new Date().toISOString().slice(0, 7);
        const totalCost = safeExpenses.filter(e => e.month === targetMonth).reduce((s, e) => s + e.value, 0);
        const revenue = safeRevenue.find(r => r.month === targetMonth)?.revenue || 0;
        if (revenue === 0) return 0;
        return (totalCost / revenue) * 100;
    }
  };

  const calculateTotalCfiPercent = () => {
    const fixedCostPct = calculateFixedCostPercent();
    const avgCardRate = (state.cfi.debitTax + state.cfi.creditTax) / 2;
    return fixedCostPct + avgCardRate + state.cfi.tax + state.cfi.royalties + state.cfi.marketing + state.cfi.voucherTax;
  };

  const getSortedProducts = () => {
      const catOrderMap: Record<string, number> = {};
      (state.menuCategories || []).forEach(c => catOrderMap[c.name] = c.order);

      return [...(state.products || [])].sort((a, b) => {
          const orderA = catOrderMap[a.category] ?? 999;
          const orderB = catOrderMap[b.category] ?? 999;
          if (orderA !== orderB) return orderA - orderB;
          return a.order - b.order;
      });
  };

  return (
    <AppContext.Provider value={{
      ...state,
      addIngredient, updateIngredient, deleteIngredient,
      addProduct, updateProduct, deleteProduct, reorderProduct,
      addMenuCategory, updateMenuCategory, deleteMenuCategory, reorderMenuCategory,
      addCombo, updateCombo, deleteCombo,
      addExpense, updateExpense, addExpenseWithInstallments,
      addCategory, deleteCategory,
      addSupplier, deleteSupplier,
      updateCfi, updatePlatformConfig, updateMonthlyRevenue, updateStoreInfo,
      setFixedCostMode,
      getIngredientRealCost, getProductCMV, calculateFixedCostPercent, calculateTotalCfiPercent,
      getSortedProducts
    }}>
      {children}
    </AppContext.Provider>
  );
};

export const useApp = () => {
  const context = useContext(AppContext);
  if (context === undefined) throw new Error('useApp must be used within an AppProvider');
  return context;
};

import React, { useState, useMemo } from 'react';
import { useApp } from '../context/AppContext';
import { Product } from '../types';
import { Plus, Trash, Edit2, Search, FileText, X, ChefHat, HelpCircle, ChevronUp, ChevronDown, ListOrdered, Settings, Check, AlertCircle } from 'lucide-react';

const Products: React.FC = () => {
  const { 
    products, 
    ingredients, 
    menuCategories,
    addProduct, 
    updateProduct, 
    deleteProduct, 
    reorderProduct,
    addMenuCategory,
    updateMenuCategory,
    deleteMenuCategory,
    reorderMenuCategory,
    getProductCMV, 
    getIngredientRealCost,
    getSortedProducts
  } = useApp();

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isCatModalOpen, setIsCatModalOpen] = useState(false);
  const [editingProduct, setEditingProduct] = useState<Product | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [showHelp, setShowHelp] = useState(false);

  // Form State
  const [prodName, setProdName] = useState('');
  const [prodCategory, setProdCategory] = useState('');
  const [newCatName, setNewCatName] = useState('');
  const [editingCatId, setEditingCatId] = useState<string | null>(null);
  const [editingCatName, setEditingCatName] = useState('');
  const [deletingCatId, setDeletingCatId] = useState<string | null>(null);

  // Guard: Ensure menuCategories is array
  const sortedCategories = useMemo(() => [...(menuCategories || [])].sort((a,b) => a.order - b.order), [menuCategories]);
  // Guard: getSortedProducts internally checks, but double check usage
  const sortedProducts = useMemo(() => getSortedProducts(), [products, menuCategories]);

  // Grouped and Filtered
  const filteredProductsByGroup = useMemo(() => {
    const term = searchTerm.toLowerCase();
    const groups: Record<string, Product[]> = {};

    sortedCategories.forEach(cat => groups[cat.name] = []);
    groups['Sem Categoria'] = [];

    (sortedProducts || []).forEach(p => {
        if (p.name.toLowerCase().includes(term)) {
            if (groups[p.category]) groups[p.category].push(p);
            else groups['Sem Categoria'].push(p);
        }
    });

    return groups;
  }, [sortedProducts, sortedCategories, searchTerm]);

  const openNewProductModal = () => {
    setEditingProduct(null);
    setProdName('');
    setProdCategory(sortedCategories[0]?.name || 'Geral');
    setIsModalOpen(true);
