                        <tfoot className="bg-gray-50 dark:bg-gray-950/50">
                            <tr>
                                <td colSpan={3} className="px-6 py-4 text-right text-[10px] font-black uppercase text-gray-400">Total Lançamentos Extras (Simulação)</td>
