                        <span className="text-[11px] text-gray-500 dark:text-gray-400 uppercase font-black block mb-1">Qtd Produtos</span>
                        <span className="text-2xl font-black text-gray-900 dark:text-gray-200">{items.length}</span>
                     </div>
                     <div className="bg-gray-50 dark:bg-gray-800/50 p-5 rounded-xl border border-gray-200 dark:border-gray-700 shadow-sm">
                        <span className="text-[11px] text-gray-500 dark:text-gray-400 uppercase font-black block mb-1">CFI da Empresa</span>
                        <span className="text-2xl font-black text-gray-900 dark:text-gray-200">{totalCfiPercent.toFixed(2)}%</span>
                     </div>
                     <div className="bg-gray-50 dark:bg-gray-800/50 p-5 rounded-xl border border-gray-200 dark:border-gray-700 shadow-sm">
                        <span className="text-[11px] text-gray-500 dark:text-gray-400 uppercase font-black block mb-1">CMV Combo</span>
                        <span className="text-2xl font-black text-gray-900 dark:text-gray-200">R$ {cmvCombo.toFixed(2)}</span>
