                 {/* LINHA 3: Items Table */}
                 <div className="bg-white dark:bg-gray-950 border border-gray-200 dark:border-gray-800 rounded-2xl overflow-hidden mt-4 shadow-md">
                    <div className="bg-gray-50 dark:bg-[#0f111a] px-6 py-4 border-b border-gray-200 dark:border-gray-800 flex justify-between items-center">
                       <h4 className="text-sm font-black text-gray-900 dark:text-white uppercase flex items-center gap-2">
                          <ShoppingBag size={18} className="text-brand-red"/> Produtos do Combo
                       </h4>
                       <button onClick={addItem} className="text-xs bg-brand-red hover:bg-red-700 text-white px-6 py-2.5 rounded-lg transition flex items-center gap-2 font-black shadow-lg shadow-red-900/20 uppercase tracking-wider">
                          <Plus size={16} /> Adicionar Item
