                           <tbody className="divide-y divide-gray-100 dark:divide-gray-800 text-sm">
                              {items.map((item, idx) => {
                                 const product = products.find(p => p.id === item.productId);
                                 const cmvUnit = product ? getProductCMV(product) : 0;

                                 return (
                                    <tr key={idx} className="hover:bg-gray-50 dark:hover:bg-gray-900/50 transition">
                                       <td className="px-6 py-4">
                                          <select 
                                            className="bg-white dark:bg-gray-800 border border-gray-300 dark:border-gray-700 text-gray-900 dark:text-white text-sm p-3 rounded-lg w-full outline-none focus:border-brand-red font-bold"
                                            value={item.productId}
                                            onChange={e => updateItem(idx, 'productId', e.target.value)}
                                          >
                                             {(products || []).map(p => (
                                                <option key={p.id} value={p.id}>{p.name}</option>
                                             ))}
                                          </select>
                                       </td>
                                       <td className="px-6 py-4 text-center">
                                          <input 
                                            type="number" 
                                            min="1"
                                            className="bg-white dark:bg-gray-800 border border-gray-300 dark:border-gray-700 text-gray-900 dark:text-white text-sm p-3 rounded-lg w-24 text-center outline-none focus:border-brand-red font-black"
                                            value={item.quantity}
                                            onChange={e => updateItem(idx, 'quantity', parseInt(e.target.value))}
                                          />
                                       </td>
                                       <td className="px-6 py-4 text-right text-gray-500 font-mono font-bold">R$ {cmvUnit.toFixed(2)}</td>
                                       <td className="px-6 py-4 text-right text-gray-900 dark:text-gray-200 font-mono font-black text-base">R$ {(cmvUnit * item.quantity).toFixed(2)}</td>
                                       <td className="px-6 py-4 text-center">
                                          <button onClick={() => removeItem(idx)} className="text-gray-400 hover:text-red-500 transition p-2" aria-label="Remover item"><Trash size={20} /></button>
                                       </td>
                                    </tr>
                                 );
                              })}
                              {items.length === 0 && (
                                 <tr><td colSpan={5} className="px-6 py-16 text-center text-gray-500 italic text-base">Clique em "Adicionar Item" para montar seu combo e começar a faturar mais.</td></tr>
                              )}
                           </tbody>
                        </table>
                    </div>
                 </div>

                 {/* LINHAS MARKETPLACES */}
                 <div className="space-y-6 pt-6 border-t border-gray-200 dark:border-gray-800">
                     <h4 className="text-sm font-black text-gray-500 dark:text-gray-400 uppercase tracking-[0.2em] mb-4">Simulação de Preços nos Canais de Venda</h4>

                     <div className="grid grid-cols-1 xl:grid-cols-2 gap-6">
                        {/* iFood Official */}
                        <div className="grid grid-cols-1 md:grid-cols-4 gap-4 items-end bg-red-50/30 dark:bg-red-950/20 p-6 rounded-2xl border border-red-100 dark:border-red-900/30">
                            <div className="md:col-span-1">
                                <label className="text-[10px] text-red-600 dark:text-red-400 uppercase font-black mb-1 block">Taxa iFood (%)</label>
                                <input type="number" step="0.1" value={ifoodFee} onChange={e => setIfoodFee(parseFloat(e.target.value))} className="w-full bg-white dark:bg-gray-900 border border-red-200 dark:border-red-800 text-gray-900 dark:text-white rounded-lg p-3 text-sm focus:ring-1 focus:ring-red-500 outline-none font-bold" />
                            </div>
                            <div className="md:col-span-1">
                                <label className="text-[10px] text-red-600 dark:text-red-400 uppercase font-black mb-1 block">Entrega (R$)</label>
                                <input type="number" step="0.01" value={delivery} onChange={e => setDelivery(parseFloat(e.target.value))} className="w-full bg-white dark:bg-gray-900 border border-red-200 dark:border-red-800 text-gray-900 dark:text-white rounded-lg p-3 text-sm focus:ring-1 focus:ring-red-500 outline-none font-bold" />
                            </div>
                            <div className="md:col-span-1">
                                <label className="text-[10px] text-red-600 dark:text-red-400 uppercase font-black mb-1 block">Cupom (R$)</label>
                                <input type="number" step="0.01" value={coupon} onChange={e => setCoupon(parseFloat(e.target.value))} className="w-full bg-white dark:bg-gray-900 border border-red-200 dark:border-red-800 text-gray-900 dark:text-white rounded-lg p-3 text-sm focus:ring-1 focus:ring-red-500 outline-none font-bold" />
                            </div>
