/* Reset básico e garantia de altura total para a aplicação React */
html, body {
  height: 100%;
  width: 100%;
  margin: 0;
  padding: 0;
  overflow-x: hidden; /* Evita rolagem horizontal indesejada */
  background-color: var(--app-bg, #111827); /* Fallback bg color */
}

#root {
  min-height: 100vh;
  width: 100%;
  display: flex;
  flex-direction: column;
}

/* 
   Garante que o container dos gráficos Recharts tenha altura mínima definida 
   antes do JavaScript carregar, evitando o erro de "width(-1) and height(-1)"
*/
.recharts-responsive-container {
  min-height: 300px;
  width: 100%;
}

/* 
   Fallback para a animação fade-in caso o Tailwind CDN falhe ou demore.
   Isso previne que a aba fique "em branco" (invisível) por causa de opacity: 0 inicial.
*/
.animate-fade-in {
  animation: fadeIn 0.5s ease-out forwards;
}

@keyframes fadeIn {
  0% { opacity: 0; transform: translateY(10px); }
  100% { opacity: 1; transform: translateY(0); }
}

/* Estilização da barra de rolagem (mantendo consistência com o estilo inline anterior) */
::-webkit-scrollbar {
  width: 8px;
}
::-webkit-scrollbar-track {
  background: rgba(0,0,0,0.1);
}
::-webkit-scrollbar-thumb {
  background: #9CA3AF; 
  border-radius: 4px;
}
.dark ::-webkit-scrollbar-track {
  background: rgba(0,0,0,0.2);
}
.dark ::-webkit-scrollbar-thumb {
  background: #374151; 
}
::-webkit-scrollbar-thumb:hover {
