                  title="Gerenciar Categorias"
              >
                  <ListOrdered size={20} />
              </button>
              <button 
                onClick={openNewProductModal}
                className="bg-brand-red hover:bg-red-700 text-white px-4 py-2.5 rounded-lg flex items-center gap-2 font-bold transition shadow-lg shadow-red-900/20"
