export const formatPercent = (value: number | undefined | null) => {
  const val = value ?? 0;
  if (isNaN(val)) return '0,0%';
  return val.toLocaleString('pt-BR', { minimumFractionDigits: 1, maximumFractionDigits: 1 }) + '%';
};

